/* SPDX-License-Identifier: GPL-2.0-only
 * P4a fixed-slot owner lifetime derivative of Huge-IC USB transport.
 * Imported if_usb.c remains unchanged, unselected provenance.
 */
#include <linux/module.h>
#include <linux/usb.h>
#include <linux/slab.h>
#include <linux/completion.h>
#include <linux/semaphore.h>
#include <linux/skbuff.h>
#include <linux/netdevice.h>
#include "../hgic_def.h"
#include "utils.h"

#define HGIC_PKT_MAX_LEN 2560
#define HGIC_TX_URB_CNT 16
#define HGIC_RX_URB_CNT 32
#define USB_TX_HEADROM 4

struct hgic_usb;

struct hgic_usb_buf {
    struct list_head list;
    struct hgic_usb *usbdev;
    struct urb *urb;
    void *data;
    /* Conservative slot leases, not active-call counts. Never cleared by
     * callback tails or submit returns. Clear only after join + poison proof.
     */
    bool submit_reserved;
    bool callback_reserved;
};

struct hgic_usb {
    struct usb_device *udev;
    unsigned int ep_in, ep_out, ep_in_size, ep_out_size;
    struct hgic_usb_buf tx[HGIC_TX_URB_CNT];
    struct hgic_usb_buf rx[HGIC_RX_URB_CNT];
    struct list_head tx_freeq, rx_freeq, used;
    struct semaphore tx_sema;
    struct hgic_bus bus;
    unsigned int allocated_urbs;
    unsigned int tx_allocated, rx_allocated;
    unsigned int submit_slots_reserved, callback_slots_reserved;
    unsigned int tx_caller_reserved;
    /* Never completed: uncertain retirement must not return/module-unload. */
    struct completion quarantine;
};

static hgic_probe probe_hdl;
static void hgic_usb_receive(struct urb *urb);
static void hgic_usb_tx_complete(struct urb *urb);

static const struct usb_device_id hgic_usb_wdev_ids[] = {
    { USB_DEVICE(HGIC_VENDOR_ID, HGIC_WLAN_8400) },
    { }
};
MODULE_DEVICE_TABLE(usb, hgic_usb_wdev_ids);

static void hgic_usb_close(struct hgic_usb *usb)
{
    unsigned long flags;
    spin_lock_irqsave(&usb->bus.owner_lock, flags);
    usb->bus.stopping = true;
    spin_unlock_irqrestore(&usb->bus.owner_lock, flags);
}

static void hgic_usb_fail(struct hgic_usb *usb, int error, unsigned int phase)
{
    hgic_attach_error(error, phase); /* preserve exact first cause before STOP */
    hgic_usb_close(usb);
}

static __noreturn void hgic_usb_quarantine(struct hgic_usb *usb)
{
    hgic_usb_fail(usb, -EUCLEAN, HGIC_ATTACH_PROBE);
    /* No allocation free, callback skip, timeout, magic success or return.
     * A blocked disconnect/module exit retains module text as well as owners.
     * Later P5 must supply actual bounded recovery; this is not a watchdog.
     */
    for (;;)
        wait_for_completion(&usb->quarantine);
}

/* owner_lock held. One sticky reservation per immutable slot covers callback
 * reentry/resubmit and a callback preceding the outer submit return. It does
 * not pretend to count accepted URBs or currently executing callbacks.
 */
static void hgic_usb_reserve_slot(struct hgic_usb_buf *buf)
{
    struct hgic_usb *usb = buf->usbdev;
    lockdep_assert_held(&usb->bus.owner_lock);
    if (!buf->submit_reserved) {
        buf->submit_reserved = true;
        usb->submit_slots_reserved++;
    }
    if (!buf->callback_reserved) {
        buf->callback_reserved = true;
        usb->callback_slots_reserved++;
    }
}

static void hgic_usb_requeue(struct hgic_usb_buf *buf, struct list_head *head)
{
    unsigned long flags;
    struct hgic_usb *usb = buf->usbdev;
    spin_lock_irqsave(&usb->bus.owner_lock, flags);
    list_move_tail(&buf->list, head);
    spin_unlock_irqrestore(&usb->bus.owner_lock, flags);
}

static void hgic_usb_init_slots(struct hgic_usb *usb)
{
    unsigned int i;
    INIT_LIST_HEAD(&usb->tx_freeq);
    INIT_LIST_HEAD(&usb->rx_freeq);
    INIT_LIST_HEAD(&usb->used);
    for (i = 0; i < HGIC_TX_URB_CNT; i++) {
        usb->tx[i].usbdev = usb;
        INIT_LIST_HEAD(&usb->tx[i].list);
    }
    for (i = 0; i < HGIC_RX_URB_CNT; i++) {
        usb->rx[i].usbdev = usb;
        INIT_LIST_HEAD(&usb->rx[i].list);
    }
}

static int hgic_usb_alloc_slots(struct hgic_usb *usb)
{
    unsigned int i;
    for (i = 0; i < HGIC_TX_URB_CNT; i++) {
        struct hgic_usb_buf *buf = &usb->tx[i];
        buf->urb = usb_alloc_urb(0, GFP_KERNEL);
        if (!buf->urb)
            return -ENOMEM;
        usb->allocated_urbs++;
        list_add_tail(&buf->list, &usb->tx_freeq);
        usb->tx_allocated++;
    }
    for (i = 0; i < HGIC_RX_URB_CNT; i++) {
        struct hgic_usb_buf *buf = &usb->rx[i];
        buf->urb = usb_alloc_urb(0, GFP_KERNEL);
        if (!buf->urb)
            return -ENOMEM;
        usb->allocated_urbs++;
        /* Keep the current URB in its fixed slot even if backing fails. */
        buf->data = kmalloc(HGIC_PKT_MAX_LEN, GFP_KERNEL);
        if (!buf->data)
            return -ENOMEM;
        list_add_tail(&buf->list, &usb->rx_freeq);
        usb->rx_allocated++;
    }
    return 0;
}

static int hgic_usb_submit_rx(struct hgic_usb_buf *buf)
{
    struct hgic_usb *usb = buf->usbdev;
    unsigned long flags;
    int error;
    spin_lock_irqsave(&usb->bus.owner_lock, flags);
    if (usb->bus.stopping || READ_ONCE(usb->bus.rx_failed) || hgic_attach_failed()) {
        list_move_tail(&buf->list, &usb->rx_freeq);
        spin_unlock_irqrestore(&usb->bus.owner_lock, flags);
        return -ESHUTDOWN;
    }
    list_move_tail(&buf->list, &usb->used);
    hgic_usb_reserve_slot(buf);
    spin_unlock_irqrestore(&usb->bus.owner_lock, flags);

    /* A pre-STOP admitted callback may still reach this entry. Retirement
     * retains this slot and permanently poisons it, waiting for actual return.
     */
    usb_fill_bulk_urb(buf->urb, usb->udev, usb_rcvbulkpipe(usb->udev, usb->ep_in),
                      buf->data, HGIC_PKT_MAX_LEN, hgic_usb_receive, buf);
    error = usb_submit_urb(buf->urb, GFP_ATOMIC);
    if (error) {
        /* HCD did not accept: no callback for this submission. This local
         * owner alone requeues it; never fabricate HCD completion/retirement.
         */
        hgic_usb_fail(usb, error, HGIC_ATTACH_RX_SUBMIT);
        hgic_usb_requeue(buf, &usb->rx_freeq);
        if (usb->bus.rx_error)
            usb->bus.rx_error(usb->bus.bus_priv);
        return error;
    }
    /* Immediate callback may have consumed/resubmitted it: no buf/URB access. */
    return 0;
}

static void hgic_usb_receive(struct urb *urb)
{
    struct hgic_usb_buf *buf = urb->context;
    struct hgic_usb *usb = buf->usbdev;
    unsigned long flags;
    int error;

    /* Serialize RX dispatch admission, but never hold it over parser/callback. */
    spin_lock_irqsave(&usb->bus.owner_lock, flags);
    if (usb->bus.stopping) {
        list_move_tail(&buf->list, &usb->rx_freeq);
        spin_unlock_irqrestore(&usb->bus.owner_lock, flags);
        return;
    }
    spin_unlock_irqrestore(&usb->bus.owner_lock, flags);
    if (READ_ONCE(usb->bus.rx_failed) || hgic_attach_failed() || urb->status ||
        !buf->data || urb->transfer_buffer != buf->data ||
        urb->transfer_buffer_length != HGIC_PKT_MAX_LEN ||
        urb->actual_length <= 0 || urb->actual_length > urb->transfer_buffer_length)
        goto bad_rx;
    error = usb->bus.rx_packet(usb->bus.bus_priv, buf->data, urb->actual_length);
    if (error == -EPROTO || READ_ONCE(usb->bus.rx_failed) || hgic_attach_failed())
        goto bad_rx;
    hgic_usb_submit_rx(buf);
    return;
bad_rx:
    hgic_usb_fail(usb, urb->status ? urb->status : -EPROTO, HGIC_ATTACH_RX_COMPLETE);
    WRITE_ONCE(usb->bus.rx_failed, 1);
    if (usb->bus.rx_error)
        usb->bus.rx_error(usb->bus.bus_priv);
    hgic_usb_requeue(buf, &usb->rx_freeq);
}

static void hgic_usb_tx_complete(struct urb *urb)
{
    struct hgic_usb_buf *buf = urb->context;
    struct hgic_usb *usb = buf->usbdev;
    if (urb->status)
        hgic_usb_fail(usb, urb->status, HGIC_ATTACH_TX_COMPLETE);
    usb->bus.tx_complete(usb->bus.bus_priv, buf->data, !urb->status);
    buf->data = NULL;
    hgic_usb_requeue(buf, &usb->tx_freeq);
    up(&usb->tx_sema);
    /* Leases remain reserved through the return tail. Only the later kernel
     * poison return proves this callback and its module text have returned.
     */
}

static int hgic_usb_tx_packet(void *bus, struct sk_buff *skb)
{
    struct hgic_usb *usb = container_of(bus, struct hgic_usb, bus);
    struct hgic_usb_buf *buf = NULL;
    struct hgic_hdr *hdr;
    unsigned long flags;
    bool token = false;
    int length, error;

    spin_lock_irqsave(&usb->bus.owner_lock, flags);
    if (usb->bus.stopping) {
        spin_unlock_irqrestore(&usb->bus.owner_lock, flags);
        error = -ESHUTDOWN;
        goto local_failure;
    }
    /* Actual selected caller is the single ordered core TX worker. Its full
     * return is proved by owner_stop/cancel_work_sync, not this sticky scalar.
     */
    usb->tx_caller_reserved = 1;
    spin_unlock_irqrestore(&usb->bus.owner_lock, flags);
    if (!usb->bus.attach_tx_admit || !usb->bus.bus_priv) {
        error = -EPERM;
        goto local_failure;
    }
    error = usb->bus.attach_tx_admit(usb->bus.bus_priv, skb);
    if (error)
        goto local_failure;
    if (!usb->ep_out_size || skb_is_nonlinear(skb) || skb->len != sizeof(struct hgic_ctrl_hdr)) {
        error = -EPROTO;
        goto local_failure;
    }
    hdr = (struct hgic_hdr *)skb->data;
    if (hdr->type != HGIC_HDR_TYPE_CMD) {
        error = -EPERM;
        goto local_failure;
    }
    length = ALIGN(skb->len, 4);
    if (IS_ALIGNED(length, usb->ep_out_size))
        length += 4;
    if (length > skb->len) {
        int padding = length - skb->len;
        if (skb_tailroom(skb) < padding && pskb_expand_head(skb, 0, padding, GFP_ATOMIC)) {
            error = -ENOMEM;
            goto local_failure;
        }
        skb_put_zero(skb, padding);
    }
    /* P3 remains absent: retain the inherited token budget, not a new request
     * deadline/cancellation implementation. Native use is still forbidden.
     */
    error = down_timeout(&usb->tx_sema, 1000);
    if (error)
        goto local_failure;
    token = true;
    spin_lock_irqsave(&usb->bus.owner_lock, flags);
    if (usb->bus.stopping || hgic_attach_failed() || list_empty(&usb->tx_freeq)) {
        spin_unlock_irqrestore(&usb->bus.owner_lock, flags);
        error = -ESHUTDOWN;
        goto local_failure;
    }
    buf = list_first_entry(&usb->tx_freeq, struct hgic_usb_buf, list);
    list_move_tail(&buf->list, &usb->used);
    buf->data = skb;
    hgic_usb_reserve_slot(buf); /* before USB can call back */
    spin_unlock_irqrestore(&usb->bus.owner_lock, flags);
    usb_fill_bulk_urb(buf->urb, usb->udev, usb_sndbulkpipe(usb->udev, usb->ep_out),
                      skb->data, length, hgic_usb_tx_complete, buf);
    buf->urb->transfer_flags |= URB_ZERO_PACKET;
    error = usb_submit_urb(buf->urb, GFP_ATOMIC);
    if (error)
        goto local_failure; /* no callback for a failed submit */
    /* Callback may already have freed skb/returned token/requeued buf. */
    return 0;

local_failure:
    hgic_usb_fail(usb, error, HGIC_ATTACH_TX_SUBMIT);
    if (buf) {
        buf->data = NULL;
        hgic_usb_requeue(buf, &usb->tx_freeq);
    }
    if (token)
        up(&usb->tx_sema);
    /* Local skb failure notification, explicitly NOT HCD callback proof. */
    if (usb->bus.tx_complete && usb->bus.bus_priv)
        usb->bus.tx_complete(usb->bus.bus_priv, skb, 0);
    else
        dev_kfree_skb_any(skb);
    return error;
}

static void hgic_usb_dispose(struct hgic_usb *usb)
{
    unsigned int i, poisoned = 0, submit_slots = 0, callback_slots = 0;
    hgic_usb_close(usb);
    if (usb->bus.bus_priv) {
        if (!usb->bus.owner_stop || !usb->bus.remove)
            hgic_usb_quarantine(usb);
        /* Join producers first, keeping every callback/private owner live. */
        usb->bus.owner_stop(usb->bus.bus_priv);
    }
    /* Stable enumeration, never current used/free membership. No lock held. */
    for (i = 0; i < HGIC_TX_URB_CNT; i++) {
        if (usb->tx[i].urb) {
            usb_poison_urb(usb->tx[i].urb);
            poisoned++;
        }
    }
    for (i = 0; i < HGIC_RX_URB_CNT; i++) {
        if (usb->rx[i].urb) {
            usb_poison_urb(usb->rx[i].urb);
            poisoned++;
        }
    }
    /* All core workers and every actual callback/return tail are now joined.
     * No unpoison path exists, including for never-submitted partial slots.
     */
    for (i = 0; i < HGIC_TX_URB_CNT; i++) {
        submit_slots += usb->tx[i].submit_reserved;
        callback_slots += usb->tx[i].callback_reserved;
        if (usb->tx[i].data)
            hgic_usb_quarantine(usb); /* uncertain skb owner: never guess free */
    }
    for (i = 0; i < HGIC_RX_URB_CNT; i++) {
        submit_slots += usb->rx[i].submit_reserved;
        callback_slots += usb->rx[i].callback_reserved;
    }
    if (poisoned != usb->allocated_urbs || submit_slots != usb->submit_slots_reserved ||
        callback_slots != usb->callback_slots_reserved ||
        submit_slots > HGIC_TX_URB_CNT + HGIC_RX_URB_CNT ||
        callback_slots > HGIC_TX_URB_CNT + HGIC_RX_URB_CNT)
        hgic_usb_quarantine(usb);
    /* Counters become zero only AFTER external join/poison return proof. */
    for (i = 0; i < HGIC_TX_URB_CNT; i++) {
        usb->tx[i].submit_reserved = false;
        usb->tx[i].callback_reserved = false;
    }
    for (i = 0; i < HGIC_RX_URB_CNT; i++) {
        usb->rx[i].submit_reserved = false;
        usb->rx[i].callback_reserved = false;
    }
    usb->submit_slots_reserved = 0;
    usb->callback_slots_reserved = 0;
    usb->tx_caller_reserved = 0;
    if (usb->bus.bus_priv) {
        usb->bus.remove(usb->bus.bus_priv);
        usb->bus.bus_priv = NULL;
    }
    for (i = 0; i < HGIC_TX_URB_CNT; i++)
        usb_free_urb(usb->tx[i].urb);
    for (i = 0; i < HGIC_RX_URB_CNT; i++) {
        kfree(usb->rx[i].data);
        usb_free_urb(usb->rx[i].urb);
    }
}

static int hgic_usb_probe(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct usb_device *udev = interface_to_usbdev(intf);
    struct usb_host_interface *desc = intf->cur_altsetting;
    struct hgic_usb *usb;
    unsigned int i;
    int error;
    bool device_ref = false, published = false;
    if (udev->bus->busnum != 1 || strcmp(udev->devpath, "1") ||
        udev->speed != USB_SPEED_HIGH || !udev->actconfig ||
        udev->actconfig->desc.bConfigurationValue != 1 || !desc) {
        hgic_attach_error(-ENODEV, HGIC_ATTACH_PROBE);
        return -ENODEV;
    }
    usb = kzalloc(sizeof(*usb), GFP_KERNEL);
    if (!usb) {
        hgic_attach_error(-ENOMEM, HGIC_ATTACH_PROBE);
        return -ENOMEM;
    }
    usb->udev = udev;
    spin_lock_init(&usb->bus.owner_lock);
    init_completion(&usb->quarantine);
    hgic_usb_init_slots(usb);
    sema_init(&usb->tx_sema, HGIC_TX_URB_CNT);
    usb->bus.type = HGIC_BUS_USB;
    usb->bus.dev_id = id->idProduct;
    usb->bus.drv_tx_headroom = USB_TX_HEADROM;
    usb->bus.tx_packet = hgic_usb_tx_packet;
    usb->bus.bootdl_pktlen = 2048;
    usb->bus.bootdl_cksum = HGIC_BUS_BOOTDL_CHECK_0XFD;
    usb->bus.probe = probe_hdl;
    /* Preserve P2's minimal descriptor policy. Full exact descriptors are P4. */
    for (i = 0; i < desc->desc.bNumEndpoints; i++) {
        struct usb_endpoint_descriptor *ep = &desc->endpoint[i].desc;
        if (usb_endpoint_is_bulk_in(ep)) {
            usb->ep_in_size = le16_to_cpu(ep->wMaxPacketSize);
            usb->ep_in = usb_endpoint_num(ep);
        } else if (usb_endpoint_is_bulk_out(ep)) {
            usb->ep_out_size = le16_to_cpu(ep->wMaxPacketSize);
            usb->ep_out = usb_endpoint_num(ep);
        }
    }
    usb->bus.blk_size = usb->ep_out_size;
    if (!usb->ep_in || !usb->ep_out || !usb->ep_in_size || !usb->ep_out_size) {
        error = -ENODEV;
        goto fail;
    }
    error = hgic_usb_alloc_slots(usb);
    if (error)
        goto fail;
    if (usb->tx_allocated != HGIC_TX_URB_CNT || usb->rx_allocated != HGIC_RX_URB_CNT) {
        error = -ENOMEM;
        goto fail;
    }
    error = usb->bus.probe(&udev->dev, &usb->bus);
    if (error || !usb->bus.bus_priv) {
        if (!error)
            error = -EPROTO;
        goto fail;
    }
    usb_get_dev(udev);
    device_ref = true;
    usb_set_intfdata(intf, usb);
    published = true;
    /* Exactly32 initial attempts maximum, independent of callback requeues. */
    for (i = 0; i < HGIC_RX_URB_CNT; i++) {
        error = hgic_usb_submit_rx(&usb->rx[i]);
        if (error)
            goto fail;
    }
    if (usb->bus.probe_post)
        usb->bus.probe_post(usb->bus.bus_priv);
    return 0;
fail:
    hgic_attach_error(error, HGIC_ATTACH_PROBE);
    if (published)
        usb_set_intfdata(intf, NULL);
    hgic_usb_dispose(usb);
    if (device_ref)
        usb_put_dev(udev);
    kfree(usb);
    return error;
}

static void hgic_usb_disconnect(struct usb_interface *intf)
{
    struct hgic_usb *usb = usb_get_intfdata(intf);
    if (!usb)
        return;
    usb_set_intfdata(intf, NULL); /* unpublish before either owner is invalidated */
    hgic_usb_dispose(usb); /* may block; never returns with uncertain callbacks */
    usb_put_dev(usb->udev);
    kfree(usb);
}

static struct usb_driver hgic_usb_driver = {
    .name = KBUILD_MODNAME,
    .probe = hgic_usb_probe,
    .disconnect = hgic_usb_disconnect,
    .id_table = hgic_usb_wdev_ids,
    .supports_autosuspend = 1,
};

int __init hgic_usb_init(hgic_probe probe, u32 max_pkt)
{
    int error;
    if (!probe || max_pkt) {
        hgic_attach_error(-EINVAL, HGIC_ATTACH_USB_REGISTER);
        return -EINVAL; /* fixed2560 backing; no aggregation/capacity override */
    }
    probe_hdl = probe;
    error = usb_register(&hgic_usb_driver);
    if (error)
        hgic_attach_error(error, HGIC_ATTACH_USB_REGISTER);
    return error;
}

void __exit hgic_usb_exit(void)
{
    usb_deregister(&hgic_usb_driver); /* synchronous disconnects must finish */
}

static void attach_tx_complete(void *priv, struct sk_buff *skb, int success)
{
    struct hgics_wdev *hg = priv;
    if (success) {
        hg->status.tx_ok++;
        /* Never clear BUS_ERROR or the first-error receipt on later success. */
    } else {
        hg->status.tx_fail++;
        set_bit(HGIC_BUS_FLAGS_ERROR, &hg->bus->flags);
        hgic_attach_error(-EIO, HGIC_ATTACH_TX_COMPLETE);
    }
    dev_kfree_skb_any(skb);
}

static int attach_tx_admit(void *priv, struct sk_buff *skb)
{
    struct hgics_wdev *hg = priv;
    if (test_bit(HGICS_STATE_REMOVE, &hg->state)) {
        hgic_attach_error(-ESHUTDOWN, HGIC_ATTACH_TX_ADMIT);
        return -ESHUTDOWN;
    }
    return hgic_fwctrl_attach_tx_admit(&hg->ctrl, skb);
}

static void attach_tx_work(struct work_struct *work)
{
    struct hgics_wdev *hg = container_of(work, struct hgics_wdev, tx_work);
    struct sk_buff *skb;
    unsigned long flags;
    /* One command only. No credit query, poll, sleep, retry or data loop. */
    spin_lock_irqsave(&hg->bus->owner_lock, flags);
    if (hg->bus->stopping) {
        spin_unlock_irqrestore(&hg->bus->owner_lock, flags);
        return;
    }
    skb = skb_dequeue(&hg->ctrl.txq);
    spin_unlock_irqrestore(&hg->bus->owner_lock, flags);
    if (skb) {
        if (test_bit(HGICS_STATE_REMOVE, &hg->state) || hgic_attach_failed())
            dev_kfree_skb_any(skb);
        else
            hg->bus->tx_packet(hg->bus, skb);
    }
    if (!skb_queue_empty(&hg->ctrl.txq))
        hgic_attach_error(-EPERM, HGIC_ATTACH_TX_ADMIT);
}

static void attach_schedule(struct hgic_fwctrl *ctrl)
{
    struct hgics_wdev *hg = container_of(ctrl, struct hgics_wdev, ctrl);
    /* Sole selected caller holds owner_lock across queue + work admission. */
    lockdep_assert_held(&hg->bus->owner_lock);
    if (!hg->tx_wq || hg->bus->stopping || test_bit(HGICS_STATE_REMOVE, &hg->state) || hgic_attach_failed()) {
        hgic_attach_error(-ESHUTDOWN, HGIC_ATTACH_TX_ADMIT);
        return;
    }
    queue_work(hg->tx_wq, &hg->tx_work);
}

static void attach_disabled_work(struct work_struct *work)
{
    attach_refuse(); /* detect/test cannot query, reinit, reopen or schedule init */
}

static void attach_disabled_timer(struct timer_list *timer)
{
    attach_refuse(); /* never scheduled/rearmed; no beacon or detect callback */
}

static void attach_delay_init(struct work_struct *work)
{
    struct hgics_wdev *hg = container_of(work, struct hgics_wdev, delay_init);
    unsigned long flags;
    int error;
    spin_lock_irqsave(&attach_lock, flags);
    if (attach_receipt.first_error || !attach_receipt.init_queued ||
        attach_receipt.init_state != HGIC_ATTACH_NOT_STARTED || attach_receipt.init_starts) {
        attach_error_locked(attach_receipt.first_error ? attach_receipt.first_error : -EALREADY,
                            HGIC_ATTACH_INIT);
        spin_unlock_irqrestore(&attach_lock, flags);
        return;
    }
    attach_receipt.init_state = HGIC_ATTACH_RUNNING;
    attach_receipt.init_starts = 1;
    spin_unlock_irqrestore(&attach_lock, flags);

    /* No download/RUN/boot query, soft-credit mode, MAC fallback or restart. */
    error = hgic_fwctrl_attach_fwinfo(&hg->ctrl, &hg->fwinfo);
    if (error != 24) {
        hgic_attach_error(error < 0 ? error : -EPROTO, HGIC_ATTACH_INIT);
        return;
    }
    if (hgic_attach_failed())
        return;
    hg->ctrl.fwinfo = &hg->fwinfo;
    error = attach_register_hw(hg);
    if (error) {
        hgic_attach_error(error, HGIC_ATTACH_HW_REGISTER);
        return; /* no failed-init automatic unregister/unload/retry */
    }
    /* Netdev registration/rollback/removal notifiers are RTNL serialized.
     * Reacquire it after register_hw so removal cannot pass its unlist stage
     * while the final publication still observes an older REGISTER snapshot.
     * No netdev pointer/reference or device action is needed here.
     */
    rtnl_lock();
    spin_lock_irqsave(&attach_lock, flags);
    attach_receipt.hw_registered = 1;
    if (!attach_receipt.first_error && attach_receipt.init_state == HGIC_ATTACH_RUNNING &&
        attach_receipt.proc_registered && attach_receipt.netdev_registered == 1 &&
        attach_receipt.netdev_present && !attach_receipt.netdev_removed &&
        !attach_receipt.netdev_teardown && !test_bit(HGICS_STATE_REMOVE, &hg->state) &&
        !attach_receipt.netdev_up_seen && !test_bit(HGICS_STATE_START, &hg->state) &&
        hg->radio_off) {
        attach_receipt.init_state = HGIC_ATTACH_SUCCEEDED;
        attach_receipt.init_done = 1;
    } else if (attach_receipt.netdev_teardown || test_bit(HGICS_STATE_REMOVE, &hg->state)) {
        attach_error_locked(-ECANCELED, HGIC_ATTACH_INIT);
    } else if (!attach_receipt.netdev_present || attach_receipt.netdev_removed) {
        /* Local missing-device condition, NOT the unavailable errno from a
         * later REGISTER notifier or automatic-interface creation failure.
         */
        attach_error_locked(-ENODEV, HGIC_ATTACH_NETDEV_LOST);
    } else {
        attach_error_locked(-EPROTO, HGIC_ATTACH_INIT);
    }
    spin_unlock_irqrestore(&attach_lock, flags);
    rtnl_unlock();
}

static void attach_probe_post(void *priv)
{
    struct hgics_wdev *hg = priv;
    unsigned long flags;
    unsigned long owner_flags;
    bool schedule = false;
    spin_lock_irqsave(&hg->bus->owner_lock, owner_flags);
    if (hg->bus->stopping) {
        spin_unlock_irqrestore(&hg->bus->owner_lock, owner_flags);
        return;
    }
    spin_lock_irqsave(&attach_lock, flags);
    if (!attach_receipt.first_error && !attach_receipt.init_queued &&
        attach_receipt.init_state == HGIC_ATTACH_NOT_STARTED) {
        attach_receipt.init_queued = 1;
        schedule = true;
    } else {
        attach_error_locked(attach_receipt.first_error ? attach_receipt.first_error : -EALREADY,
                            HGIC_ATTACH_INIT);
    }
    spin_unlock_irqrestore(&attach_lock, flags);
    if (schedule && !schedule_work(&hg->delay_init))
        hgic_attach_error(-EALREADY, HGIC_ATTACH_INIT);
    spin_unlock_irqrestore(&hg->bus->owner_lock, owner_flags);
}

static void attach_owner_stop(void *priv)
{
    struct hgics_wdev *hg = priv;
    unsigned long flags;
    if (!hg)
        return;
    spin_lock_irqsave(&hg->bus->owner_lock, flags);
    hg->bus->stopping = true;
    spin_unlock_irqrestore(&hg->bus->owner_lock, flags);
    set_bit(HGICS_STATE_REMOVE, &hg->state);
    clear_bit(HGICS_STATE_START, &hg->state);
    spin_lock_irqsave(&attach_lock, flags);
    /* Identifies expected core-removal notifications only; not P4 retirement. */
    attach_receipt.netdev_teardown = 1;
    if (attach_receipt.init_state == HGIC_ATTACH_NOT_STARTED ||
        attach_receipt.init_state == HGIC_ATTACH_RUNNING)
        attach_error_locked(-ECANCELED, HGIC_ATTACH_INIT);
    spin_unlock_irqrestore(&attach_lock, flags);
    if (hg->ctrl_ready)
        hgic_fwctrl_owner_stop(&hg->ctrl);
    if (hg->primitives_ready) {
        cancel_work_sync(&hg->delay_init);
        cancel_work_sync(&hg->detect_work);
        cancel_work_sync(&hg->test_work);
        del_timer_sync(&hg->detect_tmr);
        del_timer_sync(&hg->beacon_timer);
        cancel_work_sync(&hg->tx_work);
    }
    /* Core/FWCTRL/queues remain allocated until transport poison has returned
     * for every fixed slot, including URBs already moved off used lists.
     */
}

static void attach_core_remove(void *priv)
{
    struct hgics_wdev *hg = priv;
    unsigned int i;
    if (!hg)
        return;
    if (hg->hw_registered)
        ieee80211_unregister_hw(hg->hw); /* DOWN: no successful start/interface */
    if (hg->ctrl_ready)
        hgic_fwctrl_release(&hg->ctrl);
    if (hg->tx_wq)
        destroy_workqueue(hg->tx_wq);
    if (hg->hw_initialized)
        hg->hghw->ops->free(hg);
    if (hg->primitives_ready) {
        for (i = 0; i < IEEE80211_NUM_ACS; i++)
            hgic_clear_queue(&hg->data_txq[i]);
        hgic_clear_queue(&hg->trans_q);
        hgic_clear_queue(&hg->ack_q);
        hgic_clear_queue(&hg->evt_list);
    }
    /* Published core: transport has joined producers and poisoned all slots.
     * Early probe failure: no URB has yet been submitted or published.
     */
    WRITE_ONCE(attach_wiphy, NULL);
    ieee80211_free_hw(hg->hw);
}

static int attach_core_probe(void *dev, struct hgic_bus *bus)
{
    struct ieee80211_hw *hw;
    struct hgics_wdev *hg;
    unsigned long flags;
    unsigned int i;
    int error = 0;
    spin_lock_irqsave(&attach_lock, flags);
    if (attach_receipt.first_error)
        error = attach_receipt.first_error;
    else if (attach_receipt.generation)
        error = -EALREADY; /* single owned device lifetime; no rebind/recovery */
    else
        attach_receipt.generation = 1;
    spin_unlock_irqrestore(&attach_lock, flags);
    if (error)
        goto fail_receipt;
    if (bus->type != HGIC_BUS_USB || bus->dev_id != HGIC_WLAN_8400) {
        error = -ENODEV;
        goto fail_receipt;
    }
    hw = ieee80211_alloc_hw(sizeof(*hg), &attach_ops);
    if (!hw) {
        error = -ENOMEM;
        goto fail_receipt;
    }
    hg = hw->priv;
    memset(hg, 0, sizeof(*hg));
    put_unaligned_le32(0xD8833253, hg->magic);
    hg->dev = dev;
    hg->hw = hw;
    hg->bus = bus;
    hg->dev_id = bus->dev_id;
    hg->txq_size = txq_size;
    hg->radio_off = 1;
    spin_lock_init(&hg->lock);
    skb_queue_head_init(&hg->trans_q);
    skb_queue_head_init(&hg->ack_q);
    skb_queue_head_init(&hg->evt_list);
    sema_init(&hg->evt_sema, 0);
    init_completion(&hg->txwnd_cp);
    atomic_set(&hg->txwnd, 2);
    for (i = 0; i < IEEE80211_NUM_ACS; i++)
        skb_queue_head_init(&hg->data_txq[i]);
    INIT_WORK(&hg->tx_work, attach_tx_work);
    INIT_WORK(&hg->delay_init, attach_delay_init);
    INIT_WORK(&hg->detect_work, attach_disabled_work);
    INIT_WORK(&hg->test_work, attach_disabled_work);
    timer_setup(&hg->detect_tmr, attach_disabled_timer, 0);
    timer_setup(&hg->beacon_timer, attach_disabled_timer, 0);
    hg->primitives_ready = true;
    hg->hghw = hgics_hw_match(hg->dev_id);
    if (!hg->hghw) {
        error = -ENODEV;
        goto fail_hw;
    }
    hgic_fwctrl_init(&hg->ctrl, dev, bus);
    hg->ctrl_ready = true;
    if (!hg->ctrl.wq) {
        error = -ENOMEM;
        goto fail_hw;
    }
    hg->ctrl.schedule = attach_schedule;
    hg->ctrl.rx_event = hgics_rx_fw_event;
    hg->tx_wq = alloc_ordered_workqueue("hgics_attach", 0);
    if (!hg->tx_wq) {
        error = -ENOMEM;
        goto fail_hw;
    }
    hw->extra_tx_headroom = sizeof(struct hgic_frm_hdr) + bus->drv_tx_headroom + 4;
    hw->wiphy->signal_type = CFG80211_SIGNAL_TYPE_MBM;
    hw->wiphy->addresses = hg->macaddr;
    WRITE_ONCE(attach_wiphy, hw->wiphy);
    bus->tx_complete = attach_tx_complete;
    bus->attach_tx_admit = attach_tx_admit;
    bus->rx_packet = hgics_rx_data;
    bus->rx_error = hgics_rx_error;
    bus->probe_post = attach_probe_post;
    bus->owner_stop = attach_owner_stop;
    bus->remove = attach_core_remove;
    bus->bus_priv = hg; /* publication only after initialized stages */
    return 0;
fail_hw:
    hgic_attach_error(error, HGIC_ATTACH_CORE_PROBE);
    attach_owner_stop(hg);
    attach_core_remove(hg);
fail_receipt:
    hgic_attach_error(error, HGIC_ATTACH_CORE_PROBE);
    return error;

static int __init attach_module_init(void)
{
    unsigned long flags;
    int error;
    if (if_test || if_agg || hgics_dack || bt_en || no_bootdl != 1 || txq_size != 1024) {
        hgic_attach_error(-EINVAL, HGIC_ATTACH_PARAMETERS);
        return -EINVAL; /* refuse overrides, do not silently coerce them */
    }
    error = hgics_attach_status_init();
    if (error) {
        hgic_attach_error(error, HGIC_ATTACH_PROC);
        return error;
    }
    spin_lock_irqsave(&attach_lock, flags);
    attach_receipt.proc_registered = 1;
    spin_unlock_irqrestore(&attach_lock, flags);
    error = register_netdevice_notifier(&attach_netdev_notifier);
    if (error) {
        hgic_attach_error(error, HGIC_ATTACH_NOTIFIER);
        goto fail_status;
    }
    notifier_registered = true;
    error = hgic_usb_init(attach_core_probe, 0);
    if (error) {
        hgic_attach_error(error, HGIC_ATTACH_USB_REGISTER);
        goto fail_notifier;
    }
    usb_registered = true;
    spin_lock_irqsave(&attach_lock, flags);
    attach_receipt.usb_registered = 1;
    spin_unlock_irqrestore(&attach_lock, flags);
    /* Registration/no bound probe remains NOT_STARTED, never init success. */
    return 0;
fail_notifier:
    unregister_netdevice_notifier(&attach_netdev_notifier);
    notifier_registered = false;
fail_status:
    hgics_attach_status_exit();
    return error;
}

static void __exit attach_module_exit(void)
{
    if (usb_registered)
        hgic_usb_exit();
    if (notifier_registered)
        unregister_netdevice_notifier(&attach_netdev_notifier);
    hgics_attach_status_exit();
    /* No P4 final-retirement summary or safe normal-unload claim in P2. */
}

module_init(attach_module_init);
module_exit(attach_module_exit);
module_param(if_test, int, 0);
module_param(if_agg, int, 0);
module_param(hgics_dack, int, 0);
module_param(bt_en, int, 0);
module_param(no_bootdl, int, 0);
module_param(txq_size, int, 0);
MODULE_DESCRIPTION("HUGE-IC P2 attach-only source candidate; P1/P3-P5 unmet");
MODULE_AUTHOR("Dongyun; AnykaOpenCam attach-only derivative");
MODULE_LICENSE("GPL");

int hgic_fwctrl_do_cmd(struct hgic_fwctrl *ctrl, u8 ifidx, u32 cmd_id, u8 *in, u32 in_len, u8 *out, u32 out_size)
{
    int ret = -1;
    struct sk_buff *skb  = NULL;
    struct sk_buff *resp = NULL;
    struct hgic_cmd_response receipt;
    unsigned long flags;

    if ((!in && in_len) || (!out && out_size)) {
        hgic_attach_error(-EINVAL, HGIC_ATTACH_COMMAND);
        return -EINVAL;
    }
    if(in_len > 2000){
        hgic_err("data len is too long\r\n");
        hgic_attach_error(-EINVAL, HGIC_ATTACH_COMMAND);
        return -EINVAL;
    }

    spin_lock_irqsave(&ctrl->lock, flags);
    if (ctrl->attach_task != current || ctrl->attach_command ||
        cmd_id != HGIC_CMD_GET_FW_INFO || ifidx != HGIC_WDEV_ID_STA ||
        in_len || !out || out_size != 24 || hgic_attach_failed()) {
        spin_unlock_irqrestore(&ctrl->lock, flags);
        hgic_attach_error(-EPERM, HGIC_ATTACH_COMMAND);
        return hgic_attach_failed();
    }
    ctrl->attach_command = true;
    spin_unlock_irqrestore(&ctrl->lock, flags);

    skb = hgic_alloc_ctrl_skb(ctrl, in_len);
    if (skb) {
        spin_lock_irqsave(&ctrl->lock, flags);
        ctrl->attach_skb = skb;
        spin_unlock_irqrestore(&ctrl->lock, flags);
        if (in && in_len > 0) {
            memcpy(skb->data, in, in_len);
            skb->data[in_len] = 0;
        }

        resp = hgic_fwctrl_send_cmd(ctrl, ifidx, cmd_id, skb, &receipt);
        if (resp) {
            spin_lock_irqsave(&ctrl->lock, flags);
            if (hgic_attach_failed())
                ret = hgic_attach_failed();
            else if (ctrl->receipt_error)
                ret = ctrl->receipt_error;
            else
                ret = hgic_ctrl_reply_copy(resp->data, resp->len, receipt.type,
                                          receipt.ifidx, receipt.opcode, receipt.cookie,
                                          out, out_size);
            spin_unlock_irqrestore(&ctrl->lock, flags);
            dev_kfree_skb_any(resp);
        } else if (hgic_attach_failed()) {
            ret = hgic_attach_failed();
        } else if (READ_ONCE(ctrl->receipt_error)) {
            ret = READ_ONCE(ctrl->receipt_error);
        }
        if (ret < 0) {
            hgic_attach_error(ret, HGIC_ATTACH_COPY);
        }
    } else {
        ret = -ENOMEM;
        hgic_attach_error(ret, HGIC_ATTACH_COMMAND);
    }
    return ret;

/* Caller holds lock. Poison all station waiters, not a later response chosen by
 * cookie alone. Boot/maintenance ownership is NOT qualified by this A1 change.
 */
static void hgic_fwctrl_bad_receipt(struct hgic_fwctrl *ctrl)
{
    struct hgic_cmd_response *resp;

    WRITE_ONCE(ctrl->receipt_error, -EPROTO);
    WRITE_ONCE(ctrl->bus->rx_failed, 1);
    hgic_attach_error(-EPROTO, HGIC_ATTACH_RX);
    list_for_each_entry(resp, &ctrl->pd_list, list) {
        if ((resp->type == HGIC_HDR_TYPE_CMD || resp->type == HGIC_HDR_TYPE_CMD2) && !resp->done) {
            resp->done = true;
            complete(&resp->cmpl);
        }
    }
}

/* USB/core ingress uses the same locked A1 waiter/copy-admission latch. */
void hgic_fwctrl_rx_error(struct hgic_fwctrl *ctrl)
{
    unsigned long flags;

    spin_lock_irqsave(&ctrl->lock, flags);
    hgic_fwctrl_bad_receipt(ctrl);
    spin_unlock_irqrestore(&ctrl->lock, flags);
}

static int hgic_fwctrl_rx_response(struct hgic_fwctrl *ctrl, struct sk_buff *skb)
{
    int find = 0;
    unsigned long flags;
    struct hgic_cmd_response *resp = NULL;
    int status;
    u16 cookie;

    spin_lock_irqsave(&ctrl->lock, flags);
    if (!hgic_ctrl_frame_valid(skb->data, skb->len)) {
        hgic_fwctrl_bad_receipt(ctrl);
        goto unlock;
    }
    cookie = get_unaligned((const u16 *)(skb->data + 6));
    list_for_each_entry(resp, &ctrl->pd_list, list) {
        if (resp->cookie == cookie) {
            /* Duplicate/replayed completion can never replace the first skb. */
            if (resp->done)
                goto unlock;
            if (resp->type == HGIC_HDR_TYPE_CMD || resp->type == HGIC_HDR_TYPE_CMD2) {
                if (ctrl->receipt_error ||
                    hgic_ctrl_reply_status(skb->data, skb->len, resp->type,
                                           resp->ifidx, resp->opcode, resp->cookie,
                                           &status)) {
                    hgic_fwctrl_bad_receipt(ctrl);
                    goto unlock;
                }
                /* A valid associated signed failure is observed here, before
                 * publishing the response/waking its waiter. Preserve the
                 * first response and earlier error; do not call bad_receipt
                 * or copy negative-response payload. Lock order is the
                 * existing FWCTRL lock -> attach-receipt lock.
                 */
                if (status < 0)
                    hgic_attach_error(status, HGIC_ATTACH_COMMAND);
            }
            resp->skb = skb;
            resp->done = true;
            complete(&resp->cmpl);
            find = 1;
            break;
        }
    }
    if (!find)
        hgic_fwctrl_bad_receipt(ctrl); /* unknown/late association: no future TX */
unlock:
    spin_unlock_irqrestore(&ctrl->lock, flags);
    if (!find) {
        dev_kfree_skb_any(skb);
    }
    return 0;
}

struct sk_buff *hgic_fwctrl_send_data(struct hgic_fwctrl *ctrl, struct sk_buff *skb, struct hgic_cmd_response *resp, u32 timeout)
{
    unsigned long flags;
    struct hgic_ctrl_hdr *hdr;

    if (!skb || !resp || skb->len != sizeof(struct hgic_ctrl_hdr) ||
        resp->cookie > HGIC_TX_COOKIE_MASK) {
        hgic_attach_error(-EPERM, HGIC_ATTACH_COMMAND);
        dev_kfree_skb_any(skb);
        return NULL;
    }
    hdr = (struct hgic_ctrl_hdr *)skb->data;
    resp->type = hdr->hdr.type;
    resp->ifidx = hdr->hdr.ifidx;
    resp->opcode = HDR_CMDID(hdr);
    /* Direct boot/OTA/BT/tool callers cannot borrow init's command permission. */

    init_completion(&resp->cmpl);
    spin_lock_irqsave(&ctrl->lock, flags);
    if (ctrl->receipt_error || hgic_attach_failed() || ctrl->attach_task != current ||
        ctrl->attach_skb != skb || ctrl->attach_queued || !ctrl->attach_command ||
        timeout != HGIC_CMD_TIMEOUT || resp->type != HGIC_HDR_TYPE_CMD ||
        resp->ifidx != HGIC_WDEV_ID_STA ||
        resp->opcode != HGIC_CMD_GET_FW_INFO - HGIC_CMD_START ||
        le16_to_cpu(hdr->hdr.magic) != HGIC_HDR_TX_MAGIC ||
        le16_to_cpu(hdr->hdr.length) != skb->len ||
        le16_to_cpu(hdr->hdr.cookie) != resp->cookie || !ctrl->schedule) {
        spin_unlock_irqrestore(&ctrl->lock, flags);
        hgic_attach_error(-EPERM, HGIC_ATTACH_COMMAND);
        dev_kfree_skb_any(skb);
        return NULL;
    }
    ctrl->attach_queued = true;
    list_add(&resp->list, &ctrl->pd_list);
    spin_unlock_irqrestore(&ctrl->lock, flags);

    /* P4a: queue + work admission is serialized with permanent STOP.
     * Pending-list lifetime/queue eviction/deadline repair remains P3.
     */
    spin_lock_irqsave(&ctrl->bus->owner_lock, flags);
    if (ctrl->bus->stopping || hgic_attach_failed()) {
        spin_unlock_irqrestore(&ctrl->bus->owner_lock, flags);
        spin_lock_irqsave(&ctrl->lock, flags);
        list_del(&resp->list);
        spin_unlock_irqrestore(&ctrl->lock, flags);
        hgic_attach_error(-ESHUTDOWN, HGIC_ATTACH_COMMAND);
        dev_kfree_skb_any(skb);
        return NULL;
    }
    if (ctrl->txq.qlen > 4) {
        kfree_skb(skb_dequeue(&ctrl->txq));
        //hgic_err("ctrl txq full, drop data (%d)\r\n", ctrl->txq.qlen);
    }

    skb_queue_tail(&ctrl->txq, skb);
    /* Selected schedule hook requires owner_lock and only queues work. */
    ctrl->schedule(ctrl);
    spin_unlock_irqrestore(&ctrl->bus->owner_lock, flags);
    if (timeout) {
        if (!wait_for_completion_timeout(&resp->cmpl, msecs_to_jiffies(timeout))) {
            hgic_attach_error(-ETIMEDOUT, HGIC_ATTACH_COMMAND);
            /* P3 must cancel owned UNSENT work; P2 does not free an async skb
             * or attach this stack waiter to it as a cancellation shortcut.
             */
        }
    }
    spin_lock_irqsave(&ctrl->lock, flags);
    list_del(&resp->list);
    spin_unlock_irqrestore(&ctrl->lock, flags);
#ifdef __RTOS__
    deinit_completion(&resp->cmpl);
#endif
    return resp->skb;
}

void hgic_fwctrl_rx(struct hgic_fwctrl *ctrl, u8 *data, int len)
{
    struct sk_buff *skb;
    unsigned long flags;
    spin_lock_irqsave(&ctrl->bus->owner_lock, flags);
    if (ctrl->bus->stopping) {
        spin_unlock_irqrestore(&ctrl->bus->owner_lock, flags);
        return;
    }
    if (!data || len <= 0 || len > 0xffff) {
        spin_unlock_irqrestore(&ctrl->bus->owner_lock, flags);
        spin_lock_irqsave(&ctrl->lock, flags);
        hgic_fwctrl_bad_receipt(ctrl);
        spin_unlock_irqrestore(&ctrl->lock, flags);
        return;
    }
    if (ctrl->wq) {
        skb = dev_alloc_skb(len);
        if (skb) {
            memcpy(skb->data, data, len);
            skb_put(skb, len);
            skb_queue_tail(&ctrl->rxq, skb);
            queue_work(ctrl->wq, &ctrl->work);
        } else {
            spin_unlock_irqrestore(&ctrl->bus->owner_lock, flags);
            hgic_attach_error(-ENOMEM, HGIC_ATTACH_RX);
            return;
        }
    } else {
        spin_unlock_irqrestore(&ctrl->bus->owner_lock, flags);
        hgic_attach_error(-ENODEV, HGIC_ATTACH_RX);
        return;
    }
    spin_unlock_irqrestore(&ctrl->bus->owner_lock, flags);
}

void hgic_fwctrl_init(struct hgic_fwctrl *ctrl, void *dev, struct hgic_bus *bus)
{
    memset(ctrl, 0, sizeof(struct hgic_fwctrl));
    ctrl->dev = dev;
    ctrl->bus = bus;
    ctrl->radio_onoff = 0;
    spin_lock_init(&ctrl->lock);
    INIT_LIST_HEAD(&ctrl->pd_list);
    skb_queue_head_init(&ctrl->rxq);
    skb_queue_head_init(&ctrl->txq);
    INIT_WORK(&ctrl->work, hgic_fwctrl_work);
    ctrl->wq = ALLOC_ORDERED_WORKQUEUE("fwctrl", 0);
    if (!ctrl->wq)
        hgic_attach_error(-ENOMEM, HGIC_ATTACH_CORE_PROBE);
}

void hgic_fwctrl_owner_stop(struct hgic_fwctrl *ctrl)
{
    unsigned long flags;
    struct hgic_cmd_response *resp;
    /* Called after the bus admission fence is closed, outside its lock.
     * Wake only live list-owned waiters with failure before joining init.
     * A validated first response/negative status is never replaced.
     */
    spin_lock_irqsave(&ctrl->lock, flags);
    if (!ctrl->receipt_error)
        ctrl->receipt_error = -ESHUTDOWN;
    list_for_each_entry(resp, &ctrl->pd_list, list) {
        if (!resp->done) {
            resp->done = true;
            complete(&resp->cmpl);
        }
    }
    spin_unlock_irqrestore(&ctrl->lock, flags);
    cancel_work_sync(&ctrl->work);
}

void hgic_fwctrl_release(struct hgic_fwctrl *ctrl)
{
    cancel_work_sync(&ctrl->work);
    hgic_fwctrl_clear_pdlist(ctrl);
    hgic_clear_queue(&ctrl->txq);
    hgic_clear_queue(&ctrl->rxq);
#ifdef __RTOS__
    skb_queue_head_deinit(&ctrl->rxq);
    skb_queue_head_deinit(&ctrl->txq);
    spin_lock_deinit(&ctrl->lock);
#endif
    if (ctrl->wq) {
        flush_workqueue(ctrl->wq);
        destroy_workqueue(ctrl->wq);
    }
}

//command response
struct hgic_cmd_response {
    struct list_head list;
    unsigned short cookie;
    unsigned short opcode;
    unsigned char type;
    unsigned char ifidx;
    bool done; /* first response wins, including a signed firmware error */
    struct completion cmpl;
    struct sk_buff   *skb;
};

struct hgic_fwctrl {
    struct device      *dev;
    u16                 cookie;
    int                 receipt_error; /* inhibits subsequent station admission */
    /* Local P2 ownership only. Never store the stack response in an skb/URB.
     * Queue/URB/request cancellation and submit serialization remain P3.
     */
    struct task_struct *attach_task;
    struct sk_buff *attach_skb; /* identity comparison only, not an extra ref */
    bool attach_called;
    bool attach_command;
    bool attach_queued;
    bool attach_tx_consumed;
    spinlock_t          lock;    /*ctrl packet pending lock*/
    struct list_head    pd_list; /*ctrl packet pending queue (for sync cmd)*/
    struct sk_buff_head rxq;   /*fw ctrl packet rx queue*/
    struct sk_buff_head txq;   /*fw ctrl packet tx queue*/
    struct work_struct  work;  /*fw ctrl rx packet process work*/
    struct workqueue_struct *wq;
    u8                  qc_mode;
    u8                  radio_onoff;
    struct hgic_fw_info *fwinfo;
    struct hgic_bus *bus;
    void (*schedule)(struct hgic_fwctrl *ctrl);
    void (*rx_event)(struct hgic_fwctrl *ctrl, struct sk_buff *skb);
};

