struct hgic_bus {
    /* P4a permanent admission fence, initialized before core publication.
     * No submit/callback/join/poison runs while holding this lock.
     */
    spinlock_t owner_lock;
    bool stopping;
    int type;
    int dev_id;
    int drv_tx_headroom;
    void *bus_priv;
    unsigned long flags;
    int bootdl_pktlen;
    int bootdl_cksum;
    int blk_size;
    int (*probe)(void *dev, struct hgic_bus *bus);
    int (*tx_packet)(void *bus, struct sk_buff *skb);
    /* P2: consume permission for the sole init-owned skb, never a wire token. */
    int (*attach_tx_admit)(void *hg, struct sk_buff *skb);
    void (*tx_complete)(void *hg, struct sk_buff *skb, int success);
    int (*rx_packet)(void *hg, u8 *data, int len);
    /* Internal RX rejection only; no query/recovery or backing ownership change. */
    void (*rx_error)(void *hg);
    int rx_failed; /* sticky for this bus lifetime; checked before RX submission */
    int (*reinit)(void *bus);
    void (*probe_post)(void *priv);
    /* Join all core producers without destroying callback/private owners. */
    void (*owner_stop)(void *priv);
    void (*remove)(void *priv);
    int (*suspend)(void *priv);
    int (*resume)(void *priv);
};

static int attach_status_show(struct seq_file *seq, void *unused)
{
    struct hgic_attach_receipt r;
    hgic_attach_snapshot(&r);
    seq_puts(seq, "policy=owner-lifetime-p4a-source01 schema=2\n");
    seq_printf(seq, "generation=%u init=%u queued=%u starts=%u done=%u fwinfo=%u\n",
               r.generation, r.init_state, r.init_queued, r.init_starts,
               r.init_done, r.fwinfo_commands);
    seq_printf(seq, "first_error=%d first_phase=%u hw_registered=%u netdev_registered=%u "
               "netdev_up_seen=%u proc_registered=%u usb_registered=%u\n",
               r.first_error, r.first_phase, r.hw_registered, r.netdev_registered,
               r.netdev_up_seen, r.proc_registered, r.usb_registered);
    seq_printf(seq, "netdev_present=%u netdev_removed=%u netdev_teardown=%u "
               "netdev_removal_expected=%u\n",
               r.netdev_present, r.netdev_removed, r.netdev_teardown,
               r.netdev_removal_expected);
    return 0;
}

static int attach_status_open(struct inode *inode, struct file *file)
{
    return single_open(file, attach_status_show, NULL);
}

static const struct proc_ops attach_status_ops = {
    .proc_open = attach_status_open,
    .proc_read = seq_read,
    .proc_lseek = seq_lseek,
    .proc_release = single_release,
};

int hgics_attach_status_init(void)
{
    attach_root = proc_mkdir("hgics", NULL);
    if (!attach_root)
        return -ENOMEM; /* proc_mkdir exposes NULL, not a more specific errno */
    attach_status = proc_create_data("status", 0444, attach_root, &attach_status_ops, NULL);
    if (!attach_status) {
        proc_remove(attach_root);
        attach_root = NULL;
        return -ENOMEM;
    }
    return 0;
}

void hgics_attach_status_exit(void)
{
    if (attach_status) {
        proc_remove(attach_status);
        attach_status = NULL;
    }
    if (attach_root) {
        proc_remove(attach_root);
        attach_root = NULL;
    }
}

static void hgics_beacon_queue(struct hgics_wdev *hg, struct sk_buff *skb, u8 beacon)
{
    struct hgic_frm_hdr *frmhdr = NULL;
    struct ieee80211_tx_info *info;
    u8 pad = ((u32)skb->data & 0x3) ? (4 - ((u32)skb->data & 0x3)) : 0;

    info   = IEEE80211_SKB_CB(skb);
    frmhdr = (struct hgic_frm_hdr *)skb_push(skb, sizeof(struct hgic_frm_hdr) + pad);
    memset(frmhdr, 0, sizeof(struct hgic_frm_hdr) + pad);
    frmhdr->hdr.magic  = cpu_to_le16(HGIC_HDR_TX_MAGIC);
    frmhdr->hdr.length = cpu_to_le16(skb->len);
    frmhdr->hdr.type   = (beacon ? HGIC_HDR_TYPE_BEACON : HGIC_HDR_TYPE_FRM);
    frmhdr->hdr.ifidx  = 0;
    frmhdr->hdr.flags  = pad;
    frmhdr->tx_info.band   = info->band;
    frmhdr->tx_info.tx_mcs = 0xff;
    frmhdr->tx_info.tx_bw  = 0xff;
    frmhdr->tx_info.tx_flags  = info->flags;
    frmhdr->tx_info.tx_flags2 = 0;
    if (!beacon) {
        frmhdr->tx_info.tx_flags2 |= HGIC_HDR_FLAGS2_AFT_BEACON;
    }
    skb_queue_tail(&hg->data_txq[0], skb);
    queue_work(hg->tx_wq, &hg->tx_work);
}

#if !defined(__RTOS__) && LINUX_VERSION_CODE >= KERNEL_VERSION(4,14,0)
void hgics_mac80211_beacon(struct timer_list *t)
{
    struct hgics_wdev *hg = from_timer(hg, t, beacon_timer);
#else
void hgics_mac80211_beacon(unsigned long arg)
{
    struct hgics_wdev *hg = (struct hgics_wdev *)arg;
#endif
    struct ieee80211_hw *hw = hg->hw;

    if (test_bit(HGICS_STATE_REMOVE, &hg->state)) {
        return;
    }
    IEEE80211_ITERATE_ACTIVE_INTERFACES_ATOMIC(hw, IEEE80211_IFACE_ITER_NORMAL, hgics_mac80211_beacon_tx, hg);
    mod_timer(&hg->beacon_timer, jiffies + msecs_to_jiffies(hg->beacon_int));
}

void hgics_ap_reset_beacon(struct ieee80211_hw *hw,        struct ieee80211_vif *vif, struct ieee80211_bss_conf *info)
{
    struct hgics_wdev *hg = (struct hgics_wdev *)hw->priv;
    struct hgics_vif  *hgvif = (struct hgics_vif *)vif->drv_priv;

    if (vif->type == NL80211_IFTYPE_AP || vif->type == NL80211_IFTYPE_AP_VLAN) {
        set_bit(HGICS_VIF_STATE_BEACON, &hgvif->state);
        del_timer(&hg->beacon_timer);
        if (info->enable_beacon) {
            mod_timer(&hg->beacon_timer, jiffies + msecs_to_jiffies(hg->beacon_int));
        }
    }
}

/**
 * usb_kill_urb - cancel a transfer request and wait for it to finish
 * @urb: pointer to URB describing a previously submitted request,
 *	may be NULL
 *
 * This routine cancels an in-progress request.  It is guaranteed that
 * upon return all completion handlers will have finished and the URB
 * will be totally idle and available for reuse.  These features make
 * this an ideal way to stop I/O in a disconnect() callback or close()
 * function.  If the request has not already finished or been unlinked
 * the completion handler will see urb->status == -ENOENT.
 *
 * While the routine is running, attempts to resubmit the URB will fail
 * with error -EPERM.  Thus even if the URB's completion handler always
 * tries to resubmit, it will not succeed and the URB will become idle.
 *
 * The URB must not be deallocated while this routine is running.  In
 * particular, when a driver calls this routine, it must insure that the
 * completion handler cannot deallocate the URB.
 *
 * This routine may not be used in an interrupt context (such as a bottom
 * half or a completion handler), or when holding a spinlock, or in other
 * situations where the caller can't schedule().
 *
 * This routine should not be called by a driver after its disconnect
 * method has returned.
 */
void usb_kill_urb(struct urb *urb)
{
	might_sleep();
	if (!(urb && urb->dev && urb->ep))
		return;
	atomic_inc(&urb->reject);
	/*
	 * Order the write of urb->reject above before the read
	 * of urb->use_count below.  Pairs with the barriers in
	 * __usb_hcd_giveback_urb() and usb_hcd_submit_urb().
	 */
	smp_mb__after_atomic();

	usb_hcd_unlink_urb(urb, -ENOENT);
	wait_event(usb_kill_urb_queue, atomic_read(&urb->use_count) == 0);

	atomic_dec(&urb->reject);
}
EXPORT_SYMBOL_GPL(usb_kill_urb);

/**
 * usb_poison_urb - reliably kill a transfer and prevent further use of an URB
 * @urb: pointer to URB describing a previously submitted request,
 *	may be NULL
 *
 * This routine cancels an in-progress request.  It is guaranteed that
 * upon return all completion handlers will have finished and the URB
 * will be totally idle and cannot be reused.  These features make
 * this an ideal way to stop I/O in a disconnect() callback.
 * If the request has not already finished or been unlinked
 * the completion handler will see urb->status == -ENOENT.
 *
 * After and while the routine runs, attempts to resubmit the URB will fail
 * with error -EPERM.  Thus even if the URB's completion handler always
 * tries to resubmit, it will not succeed and the URB will become idle.
 *
 * The URB must not be deallocated while this routine is running.  In
 * particular, when a driver calls this routine, it must insure that the
 * completion handler cannot deallocate the URB.
 *
 * This routine may not be used in an interrupt context (such as a bottom
 * half or a completion handler), or when holding a spinlock, or in other
 * situations where the caller can't schedule().
 *
 * This routine should not be called by a driver after its disconnect
 * method has returned.
 */
void usb_poison_urb(struct urb *urb)
{
	might_sleep();
	if (!urb)
		return;
	atomic_inc(&urb->reject);
	/*
	 * Order the write of urb->reject above before the read
	 * of urb->use_count below.  Pairs with the barriers in
	 * __usb_hcd_giveback_urb() and usb_hcd_submit_urb().
	 */
	smp_mb__after_atomic();

	if (!urb->dev || !urb->ep)
		return;

	usb_hcd_unlink_urb(urb, -ENOENT);
	wait_event(usb_kill_urb_queue, atomic_read(&urb->use_count) == 0);
}
EXPORT_SYMBOL_GPL(usb_poison_urb);

void usb_unpoison_urb(struct urb *urb)
{
	if (!urb)
		return;

	atomic_dec(&urb->reject);
}
EXPORT_SYMBOL_GPL(usb_unpoison_urb);

/**
 * usb_poison_urb - reliably kill a transfer and prevent further use of an URB
 * @urb: pointer to URB describing a previously submitted request,
 *	may be NULL
 *
 * This routine cancels an in-progress request.  It is guaranteed that
 * upon return all completion handlers will have finished and the URB
 * will be totally idle and cannot be reused.  These features make
 * this an ideal way to stop I/O in a disconnect() callback.
 * If the request has not already finished or been unlinked
 * the completion handler will see urb->status == -ENOENT.
 *
 * After and while the routine runs, attempts to resubmit the URB will fail
 * with error -EPERM.  Thus even if the URB's completion handler always
 * tries to resubmit, it will not succeed and the URB will become idle.
 *
 * The URB must not be deallocated while this routine is running.  In
 * particular, when a driver calls this routine, it must insure that the
 * completion handler cannot deallocate the URB.
 *
 * This routine may not be used in an interrupt context (such as a bottom
 * half or a completion handler), or when holding a spinlock, or in other
 * situations where the caller can't schedule().
 *
 * This routine should not be called by a driver after its disconnect
 * method has returned.
 */
void usb_poison_urb(struct urb *urb)
{
	might_sleep();
	if (!urb)
		return;
	atomic_inc(&urb->reject);
	/*
	 * Order the write of urb->reject above before the read
	 * of urb->use_count below.  Pairs with the barriers in
	 * __usb_hcd_giveback_urb() and usb_hcd_submit_urb().
	 */
	smp_mb__after_atomic();

	if (!urb->dev || !urb->ep)
		return;

	usb_hcd_unlink_urb(urb, -ENOENT);
	wait_event(usb_kill_urb_queue, atomic_read(&urb->use_count) == 0);
}
EXPORT_SYMBOL_GPL(usb_poison_urb);

/**
 * usb_hcd_link_urb_to_ep - add an URB to its endpoint queue
 * @hcd: host controller to which @urb was submitted
 * @urb: URB being submitted
 *
 * Host controller drivers should call this routine in their enqueue()
 * method.  The HCD's private spinlock must be held and interrupts must
 * be disabled.  The actions carried out here are required for URB
 * submission, as well as for endpoint shutdown and for usb_kill_urb.
 *
 * Return: 0 for no error, otherwise a negative error code (in which case
 * the enqueue() method must fail).  If no error occurs but enqueue() fails
 * anyway, it must call usb_hcd_unlink_urb_from_ep() before releasing
 * the private spinlock and returning.
 */
int usb_hcd_link_urb_to_ep(struct usb_hcd *hcd, struct urb *urb)
{
	int		rc = 0;

	spin_lock(&hcd_urb_list_lock);

	/* Check that the URB isn't being killed */
	if (unlikely(atomic_read(&urb->reject))) {
		rc = -EPERM;
		goto done;
	}

	if (unlikely(!urb->ep->enabled)) {
		rc = -ENOENT;
		goto done;
	}

	if (unlikely(!urb->dev->can_submit)) {
		rc = -EHOSTUNREACH;
		goto done;
	}

	/*
	 * Check the host controller's state and add the URB to the
	 * endpoint's queue.
	 */
	if (HCD_RH_RUNNING(hcd)) {
		urb->unlinked = 0;
		list_add_tail(&urb->urb_list, &urb->ep->urb_list);
	} else {
		rc = -ESHUTDOWN;
		goto done;
	}

int usb_hcd_submit_urb (struct urb *urb, gfp_t mem_flags)
{
	int			status;
	struct usb_hcd		*hcd = bus_to_hcd(urb->dev->bus);

	/* increment urb's reference count as part of giving it to the HCD
	 * (which will control it).  HCD guarantees that it either returns
	 * an error or calls giveback(), but not both.
	 */
	usb_get_urb(urb);
	atomic_inc(&urb->use_count);
	atomic_inc(&urb->dev->urbnum);
	usbmon_urb_submit(&hcd->self, urb);

	/* NOTE requirements on root-hub callers (usbfs and the hub
	 * driver, for now):  URBs' urb->transfer_buffer must be
	 * valid and usb_buffer_{sync,unmap}() not be needed, since
	 * they could clobber root hub response data.  Also, control
	 * URBs must be submitted in process context with interrupts
	 * enabled.
	 */

	if (is_root_hub(urb->dev)) {
		status = rh_urb_enqueue(hcd, urb, mem_flags);
	} else {
		status = map_urb_for_dma(hcd, urb, mem_flags);
		if (likely(status == 0)) {
			status = hcd->driver->urb_enqueue(hcd, urb, mem_flags);
			if (unlikely(status))
				unmap_urb_for_dma(hcd, urb);
		}
	}

	if (unlikely(status)) {
		usbmon_urb_submit_error(&hcd->self, urb, status);
		urb->hcpriv = NULL;
		INIT_LIST_HEAD(&urb->urb_list);
		atomic_dec(&urb->use_count);
		/*
		 * Order the write of urb->use_count above before the read
		 * of urb->reject below.  Pairs with the memory barriers in
		 * usb_kill_urb() and usb_poison_urb().
		 */
		smp_mb__after_atomic();

		atomic_dec(&urb->dev->urbnum);
		if (atomic_read(&urb->reject))
			wake_up(&usb_kill_urb_queue);
		usb_put_urb(urb);
	}
	return status;

static void __usb_hcd_giveback_urb(struct urb *urb)
{
	struct usb_hcd *hcd = bus_to_hcd(urb->dev->bus);
	struct usb_anchor *anchor = urb->anchor;
	int status = urb->unlinked;

	urb->hcpriv = NULL;
	if (unlikely((urb->transfer_flags & URB_SHORT_NOT_OK) &&
	    urb->actual_length < urb->transfer_buffer_length &&
	    !status))
		status = -EREMOTEIO;

	unmap_urb_for_dma(hcd, urb);
	usbmon_urb_complete(&hcd->self, urb, status);
	usb_anchor_suspend_wakeups(anchor);
	usb_unanchor_urb(urb);
	if (likely(status == 0))
		usb_led_activity(USB_LED_EVENT_HOST);

	/* pass ownership to the completion handler */
	urb->status = status;
	/*
	 * This function can be called in task context inside another remote
	 * coverage collection section, but kcov doesn't support that kind of
	 * recursion yet. Only collect coverage in softirq context for now.
	 */
	kcov_remote_start_usb_softirq((u64)urb->dev->bus->busnum);
	urb->complete(urb);
	kcov_remote_stop_softirq();

	usb_anchor_resume_wakeups(anchor);
	atomic_dec(&urb->use_count);
	/*
	 * Order the write of urb->use_count above before the read
	 * of urb->reject below.  Pairs with the memory barriers in
	 * usb_kill_urb() and usb_poison_urb().
	 */
	smp_mb__after_atomic();

	if (unlikely(atomic_read(&urb->reject)))
		wake_up(&usb_kill_urb_queue);
	usb_put_urb(urb);
}

