#ifndef HGIC_OWNED_CONTROL_H
#define HGIC_OWNED_CONTROL_H
#include <linux/refcount.h>
#include <linux/ktime.h>
#include <linux/skbuff.h>
#include <linux/build_bug.h>
#include "fwctrl.h"

enum hgic_cr_phase {
    HGIC_CR_NEW, HGIC_CR_QUEUED_UNSENT, HGIC_CR_WORKER_PREPARING,
    HGIC_CR_SUBMITTING, HGIC_CR_SUBMITTED, HGIC_CR_CALLBACK_RECONCILED,
    HGIC_CR_CANCELLED_UNSENT, HGIC_CR_LOCAL_FAILED, HGIC_CR_RETIRED,
};
enum hgic_cr_role {
    HGIC_CR_WAITER, HGIC_CR_REGISTRY, HGIC_CR_PENDING, HGIC_CR_QUEUE,
    HGIC_CR_WORKER, HGIC_CR_SUBMITTER, HGIC_CR_CALLBACK, HGIC_CR_ROLES,
};
struct hgic_control_request {
    refcount_t refs;
    bool role[HGIC_CR_ROLES];
    bool inconsistent, potentially_submitted, accepted, callback_seen, token_owned;
    bool reply_ready, notified;
    enum hgic_cr_phase phase;
    int error;
    u32 generation;
    u64 deadline_ns; /* computed before allocation, assigned once before publish */
    struct hgic_fwctrl *ctrl; /* usable only inside the P4a joined owner lifetime */
    struct sk_buff *command;
    struct hgic_cmd_response response;
    struct completion quarantine;
};
struct hgic_control_cb { struct hgic_control_request *request; };
static_assert(sizeof(struct hgic_control_cb) <= sizeof(((struct sk_buff *)0)->cb));
static_assert(sizeof(struct hgic_control_request) <= 1024);

/* Actual immutable first-error/receipt lock; not an exported kernel ABI. */
extern spinlock_t attach_lock;
int hgic_attach_cause_locked(void);
u32 hgic_attach_generation_locked(void);
void hgic_attach_fail_locked(int error, unsigned int phase);
void hgic_control_error_locked(int error);

struct hgic_control_request *hgic_control_create(struct hgic_fwctrl *ctrl);
struct hgic_control_request *hgic_control_from_skb(const struct sk_buff *skb);
int hgic_control_publish(struct hgic_control_request *r, struct sk_buff *skb);
struct hgic_control_request *hgic_control_take(struct hgic_fwctrl *ctrl);
struct sk_buff *hgic_control_command(struct hgic_control_request *r);
void hgic_control_worker_abort(struct hgic_control_request *r, int error);
void hgic_control_worker_done(struct hgic_control_request *r);
int hgic_control_prepare(struct hgic_control_request *r, struct sk_buff *skb);
int hgic_control_submit_claim(struct hgic_control_request *r, struct sk_buff *skb);
void hgic_control_submit_result(struct hgic_control_request *r, int error);
void hgic_control_local_failure(struct hgic_control_request *r, struct sk_buff *skb, int error);
void hgic_control_local_token_returned(struct hgic_control_request *r);
void hgic_control_callback(struct hgic_control_request *r, int error);
int hgic_control_reply_gate(struct hgic_control_request *r);
void hgic_control_response_published(struct hgic_control_request *r);
int hgic_control_check_locked(struct hgic_control_request *r);
unsigned long hgic_control_wait_budget(struct hgic_control_request *r);
void hgic_control_pending_done(struct hgic_control_request *r);
void hgic_control_waiter_done(struct hgic_control_request *r);
void hgic_control_stop_locked(struct hgic_fwctrl *ctrl);
void hgic_control_owner_release(struct hgic_fwctrl *ctrl);
#endif

static struct sk_buff *hgic_fwctrl_send_cmd(struct hgic_fwctrl *ctrl, u8 ifidx, u32 cmd_id, struct sk_buff *skb, struct hgic_cmd_response *resp)
{
    struct hgic_ctrl_hdr *hdr = NULL;
    u16 id = cmd_id - HGIC_CMD_START;

    /* P2: neither the opcode alone nor a caller's no_bootdl parameter grants
     * permission. Only this init worker's single allocated command is owned.
     */
    if (cmd_id != HGIC_CMD_GET_FW_INFO || ctrl->attach_task != current ||
        !ctrl->owned || resp != &ctrl->owned->response || hgic_attach_failed()) {
        hgic_attach_error(-EPERM, HGIC_ATTACH_COMMAND);
        dev_kfree_skb_any(skb);
        return NULL;
    }

    /* Response/completion/list belong to the heap request, already initialized. */
    resp->cookie = hgic_ctrl_cookie(ctrl);
    if (resp->cookie > HGIC_TX_COOKIE_MASK || ifidx != HGIC_WDEV_ID_STA) {
        hgic_attach_error(-EPERM, HGIC_ATTACH_COMMAND);
        dev_kfree_skb_any(skb);
        return NULL;
    }
    hdr = (struct hgic_ctrl_hdr *)skb_push(skb, sizeof(struct hgic_ctrl_hdr));
    memset(hdr->info, 0, sizeof(hdr->info));
    hdr->hdr.magic  = cpu_to_le16(HGIC_HDR_TX_MAGIC);
    hdr->hdr.length = cpu_to_le16(skb->len);
    hdr->hdr.cookie = cpu_to_le16(resp->cookie);
    hdr->hdr.ifidx  = ifidx;
    HDR_CMDID_SET(hdr, id);
    return hgic_fwctrl_send_data(ctrl, skb, resp, HGIC_CMD_TIMEOUT);
}

int hgic_fwctrl_do_cmd(struct hgic_fwctrl *ctrl, u8 ifidx, u32 cmd_id, u8 *in, u32 in_len, u8 *out, u32 out_size)
{
    int ret = -1;
    struct sk_buff *skb  = NULL;
    struct sk_buff *resp = NULL;
    struct hgic_control_request *request;
    unsigned long flags;

    if ((!in && in_len) || (!out && out_size)) {
        hgic_attach_error(-EINVAL, HGIC_ATTACH_COMMAND);
        return -EINVAL;
    }
    if(in_len > 2000){
        hgic_err("data len is too long\r\n");
        hgic_attach_error(-EINVAL, HGIC_ATTACH_COMMAND);
        return -EINVAL;
    }

    spin_lock_irqsave(&ctrl->lock, flags);
    if (ctrl->attach_task != current || ctrl->attach_command ||
        cmd_id != HGIC_CMD_GET_FW_INFO || ifidx != HGIC_WDEV_ID_STA ||
        in_len || !out || out_size != 24 || hgic_attach_failed()) {
        spin_unlock_irqrestore(&ctrl->lock, flags);
        hgic_attach_error(-EPERM, HGIC_ATTACH_COMMAND);
        return hgic_attach_failed();
    }
    ctrl->attach_command = true;
    spin_unlock_irqrestore(&ctrl->lock, flags);

    request = hgic_control_create(ctrl);
    if (IS_ERR(request))
        return PTR_ERR(request);

    skb = hgic_alloc_ctrl_skb(ctrl, in_len);
    if (skb) {
        if (in && in_len > 0) {
            memcpy(skb->data, in, in_len);
            skb->data[in_len] = 0;
        }

        resp = hgic_fwctrl_send_cmd(ctrl, ifidx, cmd_id, skb, &request->response);
        if (resp) {
            spin_lock_irqsave(&ctrl->lock, flags);
            spin_lock(&attach_lock);
            ret = hgic_control_check_locked(request);
            if (!ret && ctrl->receipt_error)
                ret = ctrl->receipt_error;
            else if (!ret)
                ret = hgic_ctrl_reply_copy(resp->data, resp->len, request->response.type,
                                          request->response.ifidx, request->response.opcode, request->response.cookie,
                                          out, out_size);
            request->response.skb = NULL;
            if (ret < 0)
                hgic_attach_fail_locked(ret, HGIC_ATTACH_COPY);
            spin_unlock(&attach_lock);
            spin_unlock_irqrestore(&ctrl->lock, flags);
            dev_kfree_skb_any(resp);
        } else if (hgic_attach_failed()) {
            ret = hgic_attach_failed();
        } else if (READ_ONCE(ctrl->receipt_error)) {
            ret = READ_ONCE(ctrl->receipt_error);
        }
        if (ret < 0) {
            hgic_attach_error(ret, HGIC_ATTACH_COPY);
        }
    } else {
        ret = -ENOMEM;
        hgic_attach_error(ret, HGIC_ATTACH_COMMAND);
    }
    hgic_control_waiter_done(request);
    return ret;

static int hgic_fwctrl_rx_response(struct hgic_fwctrl *ctrl, struct sk_buff *skb)
{
    int find = 0;
    unsigned long flags;
    struct hgic_cmd_response *resp = NULL;
    int status;
    u16 cookie;

    spin_lock_irqsave(&ctrl->lock, flags);
    if (!hgic_ctrl_frame_valid(skb->data, skb->len)) {
        hgic_fwctrl_bad_receipt(ctrl);
        goto unlock;
    }
    cookie = get_unaligned((const u16 *)(skb->data + 6));
    list_for_each_entry(resp, &ctrl->pd_list, list) {
        if (resp->cookie == cookie) {
            /* Duplicate/replayed completion can never replace the first skb. */
            if (resp->done)
                goto unlock;
            /* A reply cannot complete a request that never won submit claim. */
            if (hgic_control_reply_gate(container_of(resp, struct hgic_control_request, response)))
                goto unlock;
            if (resp->type == HGIC_HDR_TYPE_CMD || resp->type == HGIC_HDR_TYPE_CMD2) {
                if (ctrl->receipt_error ||
                    hgic_ctrl_reply_status(skb->data, skb->len, resp->type,
                                           resp->ifidx, resp->opcode, resp->cookie,
                                           &status)) {
                    hgic_fwctrl_bad_receipt(ctrl);
                    goto unlock;
                }
                /* A valid associated signed failure is observed here, before
                 * publishing the response/waking its waiter. Preserve the
                 * first response and earlier error; do not call bad_receipt
                 * or copy negative-response payload. Lock order is the
                 * existing FWCTRL lock -> attach-receipt lock.
                 */
                if (status < 0)
                    hgic_attach_error(status, HGIC_ATTACH_COMMAND);
            }
            resp->skb = skb;
            resp->done = true;
            hgic_control_response_published(container_of(resp, struct hgic_control_request, response));
            find = 1;
            break;
        }
    }
    if (!find)
        hgic_fwctrl_bad_receipt(ctrl); /* unknown/late association: no future TX */
unlock:
    spin_unlock_irqrestore(&ctrl->lock, flags);
    if (!find) {
        dev_kfree_skb_any(skb);
    }
    return 0;
}

struct sk_buff *hgic_fwctrl_send_data(struct hgic_fwctrl *ctrl, struct sk_buff *skb, struct hgic_cmd_response *resp, u32 timeout)
{
    unsigned long flags;
    struct hgic_ctrl_hdr *hdr;
    struct hgic_control_request *request = ctrl->owned;
    struct sk_buff *reply;
    unsigned long budget;
    int error = -EPERM;

    if (!skb || !request || resp != &request->response || skb_is_nonlinear(skb) ||
        skb->len != sizeof(struct hgic_ctrl_hdr) || resp->cookie > HGIC_TX_COOKIE_MASK) {
        hgic_attach_error(-EPERM, HGIC_ATTACH_COMMAND);
        dev_kfree_skb_any(skb);
        return NULL;
    }
    hdr = (struct hgic_ctrl_hdr *)skb->data;
    resp->type = hdr->hdr.type;
    resp->ifidx = hdr->hdr.ifidx;
    resp->opcode = HDR_CMDID(hdr);
    /* Exact heap receipt only; direct stack/maintenance callers are refused. */
    spin_lock_irqsave(&ctrl->bus->owner_lock, flags);
    spin_lock(&ctrl->lock);
    if (ctrl->bus->stopping || ctrl->receipt_error || ctrl->attach_task != current || !ctrl->attach_command ||
        timeout != HGIC_CMD_TIMEOUT || resp->type != HGIC_HDR_TYPE_CMD ||
        resp->ifidx != HGIC_WDEV_ID_STA ||
        resp->opcode != HGIC_CMD_GET_FW_INFO - HGIC_CMD_START ||
        le16_to_cpu(hdr->hdr.magic) != HGIC_HDR_TX_MAGIC ||
        le16_to_cpu(hdr->hdr.length) != skb->len ||
        le16_to_cpu(hdr->hdr.cookie) != resp->cookie || !ctrl->schedule) {
        error = -EPERM;
    } else {
        error = hgic_control_publish(request, skb);
    }
    spin_unlock(&ctrl->lock);
    if (!error)
        ctrl->schedule(ctrl); /* same sole producer, under P4a admission gate */
    spin_unlock_irqrestore(&ctrl->bus->owner_lock, flags);
    if (error) {
        hgic_attach_error(error, HGIC_ATTACH_COMMAND);
        dev_kfree_skb_any(skb); /* publication failed: never queued/async-owned */
        return NULL;
    }
    /* No skb access after publication: an error may already have canceled it. */
    budget = hgic_control_wait_budget(request);
    if (budget && !wait_for_completion_timeout(&resp->cmpl, budget))
        hgic_attach_error(-ETIMEDOUT, HGIC_ATTACH_COMMAND);
    spin_lock_irqsave(&ctrl->lock, flags);
    hgic_control_pending_done(request);
    reply = resp->skb;
    spin_unlock_irqrestore(&ctrl->lock, flags);
    return reply;

void hgic_fwctrl_owner_stop(struct hgic_fwctrl *ctrl)
{
    unsigned long flags;
    struct hgic_cmd_response *resp;
    /* Called after the bus admission fence is closed, outside its lock.
     * Wake only live list-owned waiters with failure before joining init.
     * A validated first response/negative status is never replaced.
     */
    spin_lock_irqsave(&ctrl->lock, flags);
    if (!ctrl->receipt_error)
        ctrl->receipt_error = -ESHUTDOWN;
    hgic_control_stop_locked(ctrl);
    list_for_each_entry(resp, &ctrl->pd_list, list) {
        if (!resp->done) {
            resp->done = true;
            complete(&resp->cmpl);
        }
    }
    spin_unlock_irqrestore(&ctrl->lock, flags);
    cancel_work_sync(&ctrl->work);
}

void hgic_fwctrl_release(struct hgic_fwctrl *ctrl)
{
    cancel_work_sync(&ctrl->work);
    hgic_control_owner_release(ctrl); /* P4a joins + full poison already returned */
    hgic_fwctrl_clear_pdlist(ctrl);
    hgic_clear_queue(&ctrl->txq);
    hgic_clear_queue(&ctrl->rxq);
#ifdef __RTOS__
    skb_queue_head_deinit(&ctrl->rxq);
    skb_queue_head_deinit(&ctrl->txq);
    spin_lock_deinit(&ctrl->lock);
#endif
    if (ctrl->wq) {
        flush_workqueue(ctrl->wq);
        destroy_workqueue(ctrl->wq);
    }
}

int hgic_fwctrl_get_fwinfo(struct hgic_fwctrl *ctrl, u8 ifidx, struct hgic_fw_info *info)
{
    int ret = 0;
    u8 retail[24] = {0};
    struct hgic_fw_info decoded = {0};
    if (!info) {
        hgic_attach_error(-EINVAL, HGIC_ATTACH_COMMAND);
        return -EINVAL;
    }
    /* Exact owned firmware2.1.0.1/stock REA layout, directly observed24
     * bytes. The newer mirror's app_version extends its C structure to28;
     * never substitute that host structure as the retail wire ABI.
     */
    ret = hgic_fwctrl_get_bytes(ctrl, ifidx, HGIC_CMD_GET_FW_INFO, retail, sizeof(retail));
    if (ret == sizeof(retail)) {
        if (!hgic_ctrl_retail_info_valid(retail, sizeof(retail))) {
            hgic_attach_error(-EPROTO, HGIC_ATTACH_COPY);
            return -EPROTO;
        }
        decoded.version = get_unaligned_le32(retail);
        decoded.svn_version = get_unaligned_le32(retail + 4);
        decoded.chip_id = get_unaligned_le16(retail + 8);
        decoded.cpu_id = get_unaligned_le16(retail + 10);
        memcpy(decoded.mac, retail + 12, 6);
        decoded.smt_dat = get_unaligned_le32(retail + 20);
        *info = decoded; /* no partial output or default-MAC fallback on reject */
    }
    return ret;
}

int hgic_fwctrl_attach_fwinfo(struct hgic_fwctrl *ctrl, struct hgic_fw_info *info)
{
    unsigned long flags;
    u64 deadline;
    int error;
    if (check_add_overflow(ktime_get_ns(), (u64)HGIC_CMD_TIMEOUT * NSEC_PER_MSEC, &deadline)) {
        hgic_attach_error(-EOVERFLOW, HGIC_ATTACH_COMMAND);
        return -EOVERFLOW;
    }
    spin_lock_irqsave(&ctrl->lock, flags);
    if (ctrl->attach_called || ctrl->attach_task || ctrl->attach_deadline_ns || !ctrl->wq) {
        spin_unlock_irqrestore(&ctrl->lock, flags);
        hgic_attach_error(-EPERM, HGIC_ATTACH_COMMAND);
        return hgic_attach_failed();
    }
    ctrl->attach_deadline_ns = deadline;
    error = hgic_attach_command_begin();
    if (error) {
        spin_unlock_irqrestore(&ctrl->lock, flags);
        return error;
    }
    ctrl->attach_called = true;
    ctrl->attach_task = current;
    spin_unlock_irqrestore(&ctrl->lock, flags);
    error = hgic_fwctrl_get_fwinfo(ctrl, HGIC_WDEV_ID_STA, info);
    spin_lock_irqsave(&ctrl->lock, flags);
    ctrl->attach_task = NULL;
    spin_unlock_irqrestore(&ctrl->lock, flags);
    if (error != 24)
        hgic_attach_error(error < 0 ? error : -EPROTO, HGIC_ATTACH_COPY);
    return error;
}

int hgic_fwctrl_attach_tx_admit(struct hgic_fwctrl *ctrl, struct sk_buff *skb)
{
    const struct hgic_ctrl_hdr *hdr;
    struct hgic_control_request *request = ctrl->owned;
    if (!skb || !request || hgic_control_from_skb(skb) != request ||
        skb_is_nonlinear(skb) || skb->len != sizeof(*hdr))
        goto denied;
    hdr = (const struct hgic_ctrl_hdr *)skb->data;
    if (hdr->hdr.type != HGIC_HDR_TYPE_CMD || hdr->hdr.ifidx != HGIC_WDEV_ID_STA ||
        le16_to_cpu(hdr->hdr.magic) != HGIC_HDR_TX_MAGIC ||
        le16_to_cpu(hdr->hdr.length) != skb->len ||
        HDR_CMDID(hdr) != HGIC_CMD_GET_FW_INFO - HGIC_CMD_START)
        goto denied;
    return hgic_control_prepare(request, skb); /* final claim occurs at USB entry */
denied:
    hgic_attach_error(-EPERM, HGIC_ATTACH_TX_ADMIT);
    return -EPERM;
}

DEFINE_SPINLOCK(attach_lock); /* private receipt + owned-request error domain */
static struct hgic_attach_receipt attach_receipt;
static struct wiphy *attach_wiphy;
static bool notifier_registered;
static bool usb_registered;

/* Caller holds attach_lock. Failure is sticky even following init success.
 * A later error does not retract an earlier completed init/copy receipt.
 */
static void attach_error_locked(int error, unsigned int phase)
{
    if (!attach_receipt.first_error) {
        attach_receipt.first_error = error < 0 ? error : -EIO;
        attach_receipt.first_phase = phase;
    }
    if (attach_receipt.init_state == HGIC_ATTACH_NOT_STARTED ||
        attach_receipt.init_state == HGIC_ATTACH_RUNNING) {
        attach_receipt.init_state = HGIC_ATTACH_FAILED;
        attach_receipt.init_done = 1;
    }
    hgic_control_error_locked(attach_receipt.first_error);
}

int hgic_attach_cause_locked(void)
{
    lockdep_assert_held(&attach_lock);
    return attach_receipt.first_error;
}

u32 hgic_attach_generation_locked(void)
{
    lockdep_assert_held(&attach_lock);
    return attach_receipt.generation;
}

void hgic_attach_fail_locked(int error, unsigned int phase)
{
    lockdep_assert_held(&attach_lock);
    attach_error_locked(error, phase);
}

void hgic_attach_error(int error, unsigned int phase)
{
    unsigned long flags;
    spin_lock_irqsave(&attach_lock, flags);
    attach_error_locked(error, phase);
    spin_unlock_irqrestore(&attach_lock, flags);
}

int hgic_attach_failed(void)
{
    unsigned long flags;
    int error;
    spin_lock_irqsave(&attach_lock, flags);
    error = attach_receipt.first_error;
    spin_unlock_irqrestore(&attach_lock, flags);
    return error;
}

void hgic_attach_snapshot(struct hgic_attach_receipt *out)
{
    unsigned long flags;
    spin_lock_irqsave(&attach_lock, flags);
    *out = attach_receipt;
    spin_unlock_irqrestore(&attach_lock, flags);
}

int hgic_attach_command_begin(void)
{
    unsigned long flags;
    int error = 0;
    spin_lock_irqsave(&attach_lock, flags);
    if (attach_receipt.first_error)
        error = attach_receipt.first_error;
    else if (attach_receipt.init_state != HGIC_ATTACH_RUNNING ||
             attach_receipt.fwinfo_commands)
        error = -EPERM;
    else
        attach_receipt.fwinfo_commands = 1;
    if (error)
        attach_error_locked(error, HGIC_ATTACH_COMMAND);
    spin_unlock_irqrestore(&attach_lock, flags);
    return error;
}

static void attach_tx_complete(void *priv, struct sk_buff *skb, int success)
{
    struct hgics_wdev *hg = priv;
    if (success) {
        hg->status.tx_ok++;
        /* Never clear BUS_ERROR or the first-error receipt on later success. */
    } else {
        hg->status.tx_fail++;
        set_bit(HGIC_BUS_FLAGS_ERROR, &hg->bus->flags);
        hgic_attach_error(-EIO, HGIC_ATTACH_TX_COMPLETE);
    }
    dev_kfree_skb_any(skb);
}

static int attach_tx_admit(void *priv, struct sk_buff *skb)
{
    struct hgics_wdev *hg = priv;
    if (test_bit(HGICS_STATE_REMOVE, &hg->state)) {
        hgic_attach_error(-ESHUTDOWN, HGIC_ATTACH_TX_ADMIT);
        return -ESHUTDOWN;
    }
    return hgic_fwctrl_attach_tx_admit(&hg->ctrl, skb);
}

static void attach_tx_work(struct work_struct *work)
{
    struct hgics_wdev *hg = container_of(work, struct hgics_wdev, tx_work);
    struct hgic_control_request *request;
    struct sk_buff *skb;
    /* One command only. No credit query, poll, sleep, retry or data loop. */
    request = hgic_control_take(&hg->ctrl);
    if (!request)
        return;
    skb = hgic_control_command(request);
    if (!skb || test_bit(HGICS_STATE_REMOVE, &hg->state) || hgic_attach_failed())
        hgic_control_worker_abort(request, -ESHUTDOWN);
    else
        hg->bus->tx_packet(hg->bus, skb); /* consumes worker/transport skb once */
    hgic_control_worker_done(request);
}

static void attach_schedule(struct hgic_fwctrl *ctrl)
{
    struct hgics_wdev *hg = container_of(ctrl, struct hgics_wdev, ctrl);
    /* Sole selected caller holds owner_lock across queue + work admission. */
    lockdep_assert_held(&hg->bus->owner_lock);
    if (!hg->tx_wq || hg->bus->stopping || test_bit(HGICS_STATE_REMOVE, &hg->state) || hgic_attach_failed()) {
        hgic_attach_error(-ESHUTDOWN, HGIC_ATTACH_TX_ADMIT);
        return;
    }
    queue_work(hg->tx_wq, &hg->tx_work);
}

static void attach_probe_post(void *priv)
{
    struct hgics_wdev *hg = priv;
    unsigned long flags;
    unsigned long owner_flags;
    bool schedule = false;
    spin_lock_irqsave(&hg->bus->owner_lock, owner_flags);
    if (hg->bus->stopping) {
        spin_unlock_irqrestore(&hg->bus->owner_lock, owner_flags);
        return;
    }
    spin_lock_irqsave(&attach_lock, flags);
    if (!attach_receipt.first_error && !attach_receipt.init_queued &&
        attach_receipt.init_state == HGIC_ATTACH_NOT_STARTED) {
        attach_receipt.init_queued = 1;
        schedule = true;
    } else {
        attach_error_locked(attach_receipt.first_error ? attach_receipt.first_error : -EALREADY,
                            HGIC_ATTACH_INIT);
    }
    spin_unlock_irqrestore(&attach_lock, flags);
    if (schedule && !schedule_work(&hg->delay_init))
        hgic_attach_error(-EALREADY, HGIC_ATTACH_INIT);
    spin_unlock_irqrestore(&hg->bus->owner_lock, owner_flags);
}

static void attach_owner_stop(void *priv)
{
    struct hgics_wdev *hg = priv;
    unsigned long flags;
    if (!hg)
        return;
    spin_lock_irqsave(&hg->bus->owner_lock, flags);
    hg->bus->stopping = true;
    spin_unlock_irqrestore(&hg->bus->owner_lock, flags);
    set_bit(HGICS_STATE_REMOVE, &hg->state);
    clear_bit(HGICS_STATE_START, &hg->state);
    spin_lock_irqsave(&attach_lock, flags);
    /* Identifies expected core-removal notifications only; not P4 retirement. */
    attach_receipt.netdev_teardown = 1;
    if (attach_receipt.init_state == HGIC_ATTACH_NOT_STARTED ||
        attach_receipt.init_state == HGIC_ATTACH_RUNNING)
        attach_error_locked(-ECANCELED, HGIC_ATTACH_INIT);
    spin_unlock_irqrestore(&attach_lock, flags);
    if (hg->ctrl_ready)
        hgic_fwctrl_owner_stop(&hg->ctrl);
    if (hg->primitives_ready) {
        cancel_work_sync(&hg->delay_init);
        cancel_work_sync(&hg->detect_work);
        cancel_work_sync(&hg->test_work);
        del_timer_sync(&hg->detect_tmr);
        del_timer_sync(&hg->beacon_timer);
        cancel_work_sync(&hg->tx_work);
    }
    /* Core/FWCTRL/queues remain allocated until transport poison has returned
     * for every fixed slot, including URBs already moved off used lists.
     */
}

static void attach_core_remove(void *priv)
{
    struct hgics_wdev *hg = priv;
    unsigned int i;
    if (!hg)
        return;
    if (hg->hw_registered)
        ieee80211_unregister_hw(hg->hw); /* DOWN: no successful start/interface */
    if (hg->ctrl_ready)
        hgic_fwctrl_release(&hg->ctrl);
    if (hg->tx_wq)
        destroy_workqueue(hg->tx_wq);
    if (hg->hw_initialized)
        hg->hghw->ops->free(hg);
    if (hg->primitives_ready) {
        for (i = 0; i < IEEE80211_NUM_ACS; i++)
            hgic_clear_queue(&hg->data_txq[i]);
        hgic_clear_queue(&hg->trans_q);
        hgic_clear_queue(&hg->ack_q);
        hgic_clear_queue(&hg->evt_list);
    }
    /* Published core: transport has joined producers and poisoned all slots.
     * Early probe failure: no URB has yet been submitted or published.
     */
    WRITE_ONCE(attach_wiphy, NULL);
    ieee80211_free_hw(hg->hw);
}

static void __exit attach_module_exit(void)
{
    if (usb_registered)
        hgic_usb_exit();
    if (notifier_registered)
        unregister_netdevice_notifier(&attach_netdev_notifier);
    hgics_attach_status_exit();
    /* No P4 final-retirement summary or safe normal-unload claim in P2. */
}

module_init(attach_module_init);
module_exit(attach_module_exit);
module_param(if_test, int, 0);
module_param(if_agg, int, 0);
module_param(hgics_dack, int, 0);
module_param(bt_en, int, 0);
module_param(no_bootdl, int, 0);
module_param(txq_size, int, 0);
MODULE_DESCRIPTION("HUGE-IC P2 attach-only source candidate; P1/P3-P5 unmet");
MODULE_AUTHOR("Dongyun; AnykaOpenCam attach-only derivative");
MODULE_LICENSE("GPL");

static void hgic_usb_tx_complete(struct urb *urb)
{
    struct hgic_usb_buf *buf = urb->context;
    struct hgic_usb *usb = buf->usbdev;
    struct hgic_control_request *request = hgic_control_from_skb(buf->data);
    int status = urb->status;
    if (status)
        hgic_usb_fail(usb, status, HGIC_ATTACH_TX_COMPLETE);
    usb->bus.tx_complete(usb->bus.bus_priv, buf->data, !status);
    buf->data = NULL;
    hgic_usb_requeue(buf, &usb->tx_freeq);
    up(&usb->tx_sema);
    if (request)
        hgic_control_callback(request, status); /* final request access in callback */
    /* Leases remain reserved through the return tail. Only the later kernel
     * poison return proves this callback and its module text have returned.
     */
}

static int hgic_usb_tx_packet(void *bus, struct sk_buff *skb)
{
    struct hgic_usb *usb = container_of(bus, struct hgic_usb, bus);
    struct hgic_usb_buf *buf = NULL;
    struct hgic_hdr *hdr;
    struct hgic_control_request *request = hgic_control_from_skb(skb);
    unsigned long flags;
    bool token = false;
    int length, error;

    spin_lock_irqsave(&usb->bus.owner_lock, flags);
    if (usb->bus.stopping) {
        spin_unlock_irqrestore(&usb->bus.owner_lock, flags);
        error = -ESHUTDOWN;
        goto local_failure;
    }
    /* Actual selected caller is the single ordered core TX worker. Its full
     * return is proved by owner_stop/cancel_work_sync, not this sticky scalar.
     */
    usb->tx_caller_reserved = 1;
    spin_unlock_irqrestore(&usb->bus.owner_lock, flags);
    if (!request || !usb->bus.attach_tx_admit || !usb->bus.bus_priv) {
        error = -EPERM;
        goto local_failure;
    }
    error = usb->bus.attach_tx_admit(usb->bus.bus_priv, skb);
    if (error)
        goto local_failure;
    if (!usb->ep_out_size || skb_is_nonlinear(skb) || skb->len != sizeof(struct hgic_ctrl_hdr)) {
        error = -EPROTO;
        goto local_failure;
    }
    hdr = (struct hgic_hdr *)skb->data;
    if (hdr->type != HGIC_HDR_TYPE_CMD) {
        error = -EPERM;
        goto local_failure;
    }
    length = ALIGN(skb->len, 4);
    if (IS_ALIGNED(length, usb->ep_out_size))
        length += 4;
    if (length > skb->len) {
        int padding = length - skb->len;
        if (skb_tailroom(skb) < padding && pskb_expand_head(skb, 0, padding, GFP_ATOMIC)) {
            error = -ENOMEM;
            goto local_failure;
        }
        skb_put_zero(skb, padding);
    }
    error = hgic_control_prepare(request, skb); /* remaining budget before token */
    if (error)
        goto local_failure;
    error = down_trylock(&usb->tx_sema) ? -EAGAIN : 0;
    if (error)
        goto local_failure;
    token = true;
    spin_lock_irqsave(&usb->bus.owner_lock, flags);
    if (usb->bus.stopping || list_empty(&usb->tx_freeq)) {
        spin_unlock_irqrestore(&usb->bus.owner_lock, flags);
        error = -ESHUTDOWN;
        goto local_failure;
    }
    buf = list_first_entry(&usb->tx_freeq, struct hgic_usb_buf, list);
    list_move_tail(&buf->list, &usb->used);
    buf->data = skb;
    error = hgic_control_submit_claim(request, skb);
    if (error) {
        spin_unlock_irqrestore(&usb->bus.owner_lock, flags);
        goto local_failure;
    }
    hgic_usb_reserve_slot(buf); /* before USB can call back */
    spin_unlock_irqrestore(&usb->bus.owner_lock, flags);
    usb_fill_bulk_urb(buf->urb, usb->udev, usb_sndbulkpipe(usb->udev, usb->ep_out),
                      skb->data, length, hgic_usb_tx_complete, buf);
    buf->urb->transfer_flags |= URB_ZERO_PACKET;
    error = usb_submit_urb(buf->urb, GFP_ATOMIC);
    /* Only separately referenced request memory, never skb/reused slot, is
     * touched on successful return. Error guarantees no actual callback.
     */
    hgic_control_submit_result(request, error);
    if (error)
        goto local_failure; /* no callback for a failed submit */
    /* Callback may already have freed skb/returned token/requeued buf. */
    return 0;

local_failure:
    hgic_usb_fail(usb, error, HGIC_ATTACH_TX_SUBMIT);
    if (request)
        hgic_control_local_failure(request, skb, error);
    if (buf) {
        buf->data = NULL;
        hgic_usb_requeue(buf, &usb->tx_freeq);
    }
    if (token)
        up(&usb->tx_sema);
    if (request)
        hgic_control_local_token_returned(request);
    /* Local skb failure notification, explicitly NOT HCD callback proof. */
    if (usb->bus.tx_complete && usb->bus.bus_priv)
        usb->bus.tx_complete(usb->bus.bus_priv, skb, 0);
    else
        dev_kfree_skb_any(skb);
    return error;
}

static void hgic_usb_dispose(struct hgic_usb *usb)
{
    unsigned int i, poisoned = 0, submit_slots = 0, callback_slots = 0;
    hgic_usb_close(usb);
    if (usb->bus.bus_priv) {
        if (!usb->bus.owner_stop || !usb->bus.remove)
            hgic_usb_quarantine(usb);
        /* Join producers first, keeping every callback/private owner live. */
        usb->bus.owner_stop(usb->bus.bus_priv);
    }
    /* Stable enumeration, never current used/free membership. No lock held. */
    for (i = 0; i < HGIC_TX_URB_CNT; i++) {
        if (usb->tx[i].urb) {
            usb_poison_urb(usb->tx[i].urb);
            poisoned++;
        }
    }
    for (i = 0; i < HGIC_RX_URB_CNT; i++) {
        if (usb->rx[i].urb) {
            usb_poison_urb(usb->rx[i].urb);
            poisoned++;
        }
    }
    /* All core workers and every actual callback/return tail are now joined.
     * No unpoison path exists, including for never-submitted partial slots.
     */
    for (i = 0; i < HGIC_TX_URB_CNT; i++) {
        submit_slots += usb->tx[i].submit_reserved;
        callback_slots += usb->tx[i].callback_reserved;
        if (usb->tx[i].data)
            hgic_usb_quarantine(usb); /* uncertain skb owner: never guess free */
    }
    for (i = 0; i < HGIC_RX_URB_CNT; i++) {
        submit_slots += usb->rx[i].submit_reserved;
        callback_slots += usb->rx[i].callback_reserved;
    }
    if (poisoned != usb->allocated_urbs || submit_slots != usb->submit_slots_reserved ||
        callback_slots != usb->callback_slots_reserved ||
        submit_slots > HGIC_TX_URB_CNT + HGIC_RX_URB_CNT ||
        callback_slots > HGIC_TX_URB_CNT + HGIC_RX_URB_CNT)
        hgic_usb_quarantine(usb);
    /* Counters become zero only AFTER external join/poison return proof. */
    for (i = 0; i < HGIC_TX_URB_CNT; i++) {
        usb->tx[i].submit_reserved = false;
        usb->tx[i].callback_reserved = false;
    }
    for (i = 0; i < HGIC_RX_URB_CNT; i++) {
        usb->rx[i].submit_reserved = false;
        usb->rx[i].callback_reserved = false;
    }
    usb->submit_slots_reserved = 0;
    usb->callback_slots_reserved = 0;
    usb->tx_caller_reserved = 0;
    if (usb->bus.bus_priv) {
        usb->bus.remove(usb->bus.bus_priv);
        usb->bus.bus_priv = NULL;
    }
    for (i = 0; i < HGIC_TX_URB_CNT; i++)
        usb_free_urb(usb->tx[i].urb);
    for (i = 0; i < HGIC_RX_URB_CNT; i++) {
        kfree(usb->rx[i].data);
        usb_free_urb(usb->rx[i].urb);
    }
}

static_assert(sizeof(struct hgic_ctrl_hdr) == 12, "selected control ABI");
static_assert(offsetof(struct hgic_ctrl_hdr, cmd.status) == 10, "selected CMD status");
static_assert(offsetof(struct hgic_ctrl_hdr, cmd2.status) == 10, "selected CMD2 status");

/* rx.c normalizes these three outer u16 fields to CPU endian before fwctrl_rx.
 * The remaining command/status/payload fields are still little endian.
 * Do not reinterpret the mirror's 28-byte fw_info as a retail wire object.
 */
static inline bool hgic_ctrl_frame_valid(const u8 *data, size_t len)
{
    return data && len >= sizeof(struct hgic_ctrl_hdr) && len <= 0xffff &&
           get_unaligned((const u16 *)(data + 0)) == HGIC_HDR_RX_MAGIC &&
           get_unaligned((const u16 *)(data + 4)) == len;
}

static inline bool hgic_ctrl_retail_info_valid(const u8 *data, size_t len)
{
    u8 mac[ETH_ALEN] __aligned(2);

    if (!data || len != 24 ||
        get_unaligned_le32(data) != 0x02010001 ||
        get_unaligned_le32(data + 4) != 22118 ||
        get_unaligned_le16(data + 8) != HGIC_WLAN_8400 ||
        get_unaligned_le16(data + 10) != 1)
        return false;
    /* is_valid_ether_addr requires u16 alignment on this ARM. The wire address
     * need not have it; use an aligned local copy rather than unaligned loads.
     */
    memcpy(mac, data + 12, ETH_ALEN);
    return is_valid_ether_addr(mac);
}

/* Return parser error separately from signed firmware status. In particular a
 * legitimate negative firmware status is not an unsigned payload byte count.
 * CMD.status and CMD2.status both start at offset10 in the selected source ABI;
 * offsetof keeps that fact checked by the actual C layout, not a packed guess.
 */
static inline int hgic_ctrl_reply_status(const u8 *data, size_t len,
                                       u8 type, u8 ifidx, u16 opcode,
                                       u16 cookie, int *status)
{
    const size_t payload = sizeof(struct hgic_ctrl_hdr);
    u16 actual_opcode;
    int value;

    if (!status || !hgic_ctrl_frame_valid(data, len) ||
        (type != HGIC_HDR_TYPE_CMD && type != HGIC_HDR_TYPE_CMD2) ||
        data[2] != type || (data[3] & 0x0f) != ifidx ||
        ifidx != HGIC_WDEV_ID_STA ||
        get_unaligned((const u16 *)(data + 6)) != cookie)
        return -EPROTO;
    actual_opcode = type == HGIC_HDR_TYPE_CMD ? data[8] :
                    get_unaligned_le16(data + 8);
    if (actual_opcode != opcode)
        return -EPROTO;
    value = (s16)get_unaligned_le16(data + offsetof(struct hgic_ctrl_hdr, cmd.status));
    if (opcode == HGIC_CMD_GET_FW_INFO - HGIC_CMD_START && value >= 0 &&
        (value != 24 || !hgic_ctrl_retail_info_valid(data + payload, len - payload)))
        return -EPROTO;
    *status = value;
    return 0;
}

static inline int hgic_ctrl_reply_copy(const u8 *data, size_t len,
                                     u8 type, u8 ifidx, u16 opcode, u16 cookie,
                                     u8 *out, size_t capacity)
{
    int value, error;

    if (!out && capacity)
        return -EINVAL;
    error = hgic_ctrl_reply_status(data, len, type, ifidx, opcode, cookie, &value);
    if (error)
        return error;
    /* Setters/scalar replies may return a positive scalar without payload.
     * Only a caller requesting bytes treats positive status as a byte count.
     * Negative status is returned intact; never copy even bounded error data.
     */
    if (value > 0 && out) {
        if ((size_t)value != len - sizeof(struct hgic_ctrl_hdr) ||
            (size_t)value > capacity)
            return -EMSGSIZE;
        memcpy(out, data + sizeof(struct hgic_ctrl_hdr), value);
    }
    return value;
}

void dev_kfree_skb_irq_reason(struct sk_buff *skb, enum skb_drop_reason reason);
void dev_kfree_skb_any_reason(struct sk_buff *skb, enum skb_drop_reason reason);

/*
 * It is not allowed to call kfree_skb() or consume_skb() from hardware
 * interrupt context or with hardware interrupts being disabled.
 * (in_hardirq() || irqs_disabled())
 *
 * We provide four helpers that can be used in following contexts :
 *
 * dev_kfree_skb_irq(skb) when caller drops a packet from irq context,
 *  replacing kfree_skb(skb)
 *
 * dev_consume_skb_irq(skb) when caller consumes a packet from irq context.
 *  Typically used in place of consume_skb(skb) in TX completion path
 *
 * dev_kfree_skb_any(skb) when caller doesn't know its current irq context,
 *  replacing kfree_skb(skb)
 *
 * dev_consume_skb_any(skb) when caller doesn't know its current irq context,
 *  and consumed a packet. Used in place of consume_skb(skb)
 */
static inline void dev_kfree_skb_irq(struct sk_buff *skb)
{
	dev_kfree_skb_irq_reason(skb, SKB_DROP_REASON_NOT_SPECIFIED);
}

static inline void dev_consume_skb_irq(struct sk_buff *skb)
{
	dev_kfree_skb_irq_reason(skb, SKB_CONSUMED);
}

static inline void dev_kfree_skb_any(struct sk_buff *skb)
{
	dev_kfree_skb_any_reason(skb, SKB_DROP_REASON_NOT_SPECIFIED);
}

static inline void dev_consume_skb_any(struct sk_buff *skb)
{
	dev_kfree_skb_any_reason(skb, SKB_CONSUMED);
}

struct sk_buff *__netdev_alloc_skb(struct net_device *dev, unsigned int length,
				   gfp_t gfp_mask);

/**
 *	netdev_alloc_skb - allocate an skbuff for rx on a specific device
 *	@dev: network device to receive on
 *	@length: length to allocate
 *
 *	Allocate a new &sk_buff and assign it a usage count of one. The
 *	buffer has unspecified headroom built in. Users should allocate
 *	the headroom they think they need without accounting for the
 *	built in space. The built in space is used for optimisations.
 *
 *	%NULL is returned if there is no free memory. Although this function
 *	allocates memory it can be called from an interrupt.
 */
static inline struct sk_buff *netdev_alloc_skb(struct net_device *dev,
					       unsigned int length)
{
	return __netdev_alloc_skb(dev, length, GFP_ATOMIC);
}

/* legacy helper around __netdev_alloc_skb() */
static inline struct sk_buff *__dev_alloc_skb(unsigned int length,
					      gfp_t gfp_mask)
{
	return __netdev_alloc_skb(NULL, length, gfp_mask);
}

/* legacy helper around netdev_alloc_skb() */
static inline struct sk_buff *dev_alloc_skb(unsigned int length)
{
	return netdev_alloc_skb(NULL, length);
}
